use bevy::prelude::*;
use bevy_arc_studio::{arc_core::*, camera::EditorCameraPlugin, gizmo_3d::Gizmo3dPlugin, selection::SelectionPlugin, lighting::LightingPlugin, props::PropsPlugin, scene::ScenePlugin, terrain_render::TerrainRenderPlugin, ui::UiPlugin, water::WaterPlugin};
use bevy_egui::EguiPlugin;

fn main() {
    let preset = std::env::args().nth(1).and_then(|a| match a.as_str() {
        "dusk" => Some(WorldPreset::MistyDuskLake),
        "noon" => Some(WorldPreset::SunnyAlpineNoon),
        "night" => Some(WorldPreset::MidnightCampfire),
        "dawn" => Some(WorldPreset::GoldenAutumnDawn),
        _ => None,
    });
    let spec = preset.map(WorldSpec::from_preset).unwrap_or_default();
    App::new()
        .add_plugins(DefaultPlugins.set(WindowPlugin {
            primary_window: Some(Window { title: "Bevy ArcStudio".into(), resolution: (1600, 900).into(), ..default() }),
            ..default()
        }))
        .add_plugins(EguiPlugin::default())
        .add_plugins(bevy_brp_extras::BrpExtrasPlugin::default())
        .insert_resource(spec)
        .insert_resource(UndoHistory::<WorldSpec>::default())
        .register_type::<WorldSpec>()
        .register_type::<bevy_arc_studio::camera::EditorCamera>()
        .add_plugins((TerrainRenderPlugin, WaterPlugin, PropsPlugin, ScenePlugin, EditorCameraPlugin, LightingPlugin, UiPlugin, SelectionPlugin, Gizmo3dPlugin))
        .run();
}
pub mod arc_core;
pub mod camera;
pub mod gizmo_3d;
pub mod lighting;
pub mod props;
pub mod scene;
pub mod selection;
pub mod terrain_render;
pub mod ui;
pub mod water;
//! Minimal egui panel: world presets, atmosphere toggles, transactional undo/redo.

use bevy::prelude::*;
use bevy_egui::{EguiContexts, EguiPrimaryContextPass, egui};

use crate::arc_core::*;
use crate::gizmo_3d::{GizmoMode, GizmoSpace, GizmoState};
use crate::selection::EditorSelection;

pub struct UiPlugin;

impl Plugin for UiPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(EguiPrimaryContextPass, studio_ui_system);
    }
}

fn studio_ui_system(mut contexts: EguiContexts, mut spec: ResMut<WorldSpec>, mut hist: ResMut<UndoHistory<WorldSpec>>, mut gz: ResMut<GizmoState>, sel: Res<EditorSelection>) {
    let Ok(ctx) = contexts.ctx_mut() else { return };
    let mut viewport_ui = egui::Ui::new(ctx.clone(), "viewport".into(), egui::UiBuilder::new().layer_id(egui::LayerId::background()).max_rect(ctx.viewport_rect()));
    egui::Panel::left("studio_panel").default_size(250.0).show(&mut viewport_ui, |ui| {
        ui.heading("Bevy ArcStudio");
        ui.horizontal(|ui| {
            if ui.add_enabled(hist.undo_len() > 0, egui::Button::new("Undo")).clicked() {
                if let Some(s) = hist.undo() {
                    *spec = s;
                }
            }
            if ui.add_enabled(hist.redo_len() > 0, egui::Button::new("Redo")).clicked() {
                if let Some(s) = hist.redo() {
                    *spec = s;
                }
            }
            ui.label(format!("{}/{}", hist.undo_len(), hist.redo_len()));
        });
        ui.separator();
        for (name, p) in [
            ("Misty Dusk Lake", WorldPreset::MistyDuskLake),
            ("Sunny Alpine Noon", WorldPreset::SunnyAlpineNoon),
            ("Midnight Campfire", WorldPreset::MidnightCampfire),
            ("Golden Autumn Dawn", WorldPreset::GoldenAutumnDawn),
        ] {
            if ui.button(name).clicked() {
                let before = spec.clone();
                let mut next = before.clone();
                let preset = WorldSpec::from_preset(p);
                // atmosphere only: terrain stays as generated
                next.time_of_day = preset.time_of_day;
                next.fog_color = preset.fog_color;
                next.fog_density = preset.fog_density;
                next.sun_intensity = preset.sun_intensity;
                next.god_rays = preset.god_rays;
                hist.record(name, before, next.clone());
                *spec = next;
            }
        }
        ui.separator();

        // slider drag → Begin → UpdatePreview* → Commit (one undo entry)
        let mut t = spec.time_of_day;
        let r = ui.add(egui::Slider::new(&mut t, 0.0..=24.0).text("time of day"));
        if r.drag_started() || (r.changed() && !hist.is_open() && !r.dragged()) {
            hist.begin("time_of_day", spec.clone());
        }
        if r.changed() {
            spec.time_of_day = t;
            let s = spec.clone();
            hist.update_preview(s);
        }
        if r.drag_stopped() || (r.changed() && !r.dragged() && hist.is_open()) {
            let s = spec.clone();
            hist.commit(s);
        }

        let mut s = spec.clone();
        let mut dirty = false;
        for (label, v) in [
            ("auto sun (advance time)", &mut s.auto_sun),
            ("fog", &mut s.fog_enabled),
            ("god rays", &mut s.god_rays),
            ("bloom", &mut s.bloom),
            ("reflections", &mut s.reflections),
            ("shadows", &mut s.shadows),
        ] {
            dirty |= ui.checkbox(v, label).changed();
        }
        let mut sun = s.sun_intensity;
        let r = ui.add(egui::Slider::new(&mut sun, 0.0..=2.0).text("sun intensity"));
        if r.changed() {
            s.sun_intensity = sun;
            dirty = true;
        }
        if dirty {
            hist.record("atmosphere", spec.clone(), s.clone());
            *spec = s;
        }
        ui.separator();
        ui.horizontal(|ui| {
            for (label, m) in [("Q Select", GizmoMode::Select), ("W Move", GizmoMode::Move), ("E Rotate", GizmoMode::Rotate), ("R Scale", GizmoMode::Scale)] {
                ui.selectable_value(&mut gz.mode, m, label);
            }
        });
        ui.horizontal(|ui| {
            ui.selectable_value(&mut gz.space, GizmoSpace::World, "World");
            ui.selectable_value(&mut gz.space, GizmoSpace::Local, "Local (X)");
        });
        ui.checkbox(&mut gz.snap_ground, "Snap to Ground (Shift)");
        ui.checkbox(&mut gz.align_normal, "Align to Normal");
        ui.label(format!("selected: {}", sel.selected.len()));
        ui.small("Ctrl+D duplicate · Del delete · Ctrl+Z/Y undo/redo (objects) · Ctrl drag = snap · Esc cancel");
        ui.separator();
        ui.small("RMB+WASD/QE fly · MMB/Alt+LMB orbit · Shift+MMB pan · wheel zoom · F focus");
    });
}
//! Startup scene: sun/moon, fog volume and editor camera (terrain, water and props live in their own modules).

use bevy::light::atmosphere::ScatteringMedium;
use bevy::light::{Atmosphere, FogVolume, SunDisk, VolumetricLight};
use bevy::prelude::*;

use crate::arc_core::*;
use crate::camera::EditorCamera;
use crate::lighting::{self, Moon, Sun};
pub use crate::terrain_render::TerrainGrid;

pub struct ScenePlugin;

impl Plugin for ScenePlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(PostStartup, setup_scene);
    }
}

fn setup_scene(
    mut commands: Commands,
    spec: Res<WorldSpec>,
    grid: Res<TerrainGrid>,
    mut media: ResMut<Assets<ScatteringMedium>>,
) {
    let grid = &grid.0;
    commands.spawn((
        Name::new("Sun"),
        Sun,
        DirectionalLight { shadow_maps_enabled: spec.shadows, illuminance: 100_000.0, ..default() },
        SunDisk::EARTH,
        VolumetricLight,
        lighting::cascades(),
        Transform::default().looking_to(Vec3::NEG_Y, Vec3::X),
    ));
    commands.spawn((
        Name::new("Moon"),
        Moon,
        DirectionalLight { color: Color::srgb(0.55, 0.65, 1.0), illuminance: 0.0, shadow_maps_enabled: false, ..default() },
        Transform::default().looking_to(Vec3::NEG_Y, Vec3::X),
    ));
    commands.spawn((
        Name::new("FogVolume"),
        FogVolume { density_factor: 0.02, scattering: 0.4, absorption: 0.05, ..default() },
        Transform::from_xyz(0.0, 40.0, 0.0).with_scale(Vec3::new(grid.size, 120.0, grid.size)),
    ));

    let camp = Vec3::new(spec.camp_center[0], grid.sample_height(spec.camp_center[0], spec.camp_center[1]), spec.camp_center[1]);
    let mut cam = EditorCamera { pivot: camp + Vec3::new(-14.0, 2.0, 8.0), distance: 34.0, yaw: -1.2, pitch: 0.14, ..default() };
    // dev aid: ARC_CAM="px,py,pz,yaw,pitch,distance"
    if let Some(v) = std::env::var("ARC_CAM").ok().map(|s| s.split(',').filter_map(|t| t.trim().parse::<f32>().ok()).collect::<Vec<_>>()).filter(|v| v.len() == 6) {
        (cam.pivot, cam.yaw, cam.pitch, cam.distance) = (Vec3::new(v[0], v[1], v[2]), v[3], v[4], v[5]);
        // keep the eye above the terrain
        let fwd = Vec3::new(cam.pitch.cos() * cam.yaw.sin(), -cam.pitch.sin(), cam.pitch.cos() * cam.yaw.cos());
        let eye = cam.pivot - fwd * cam.distance;
        let min_y = grid.sample_height(eye.x, eye.z) + 3.0;
        info!("ARC_CAM eye {eye:?}, ground {:.1}", min_y - 3.0);
        cam.pivot.y += (min_y - eye.y).max(0.0);
    }
    let medium = media.add(ScatteringMedium::earth(256, 256));
    let atmosphere = Atmosphere::earth(medium);
    commands.spawn((Name::new("Planet"), Transform::from_xyz(0.0, -atmosphere.inner_radius, 0.0), atmosphere));
    commands.spawn((
        Name::new("EditorCamera"),
        Camera3d::default(),
        cam,
        Transform::default(),
        lighting::camera_stack(&spec),
    ));
}
//! Object selection (doc 03): mesh-picking click → SceneObject root, 2D marquee, glowing AABB brackets.

use std::collections::HashSet;

use bevy::gizmos::config::GizmoConfigStore;
use bevy::gizmos::prelude::*;
use bevy::picking::mesh_picking::{MeshPickingCamera, MeshPickingPlugin, MeshPickingSettings};
use bevy::picking::pointer::PointerButton;
use bevy::picking::prelude::*;
use bevy::prelude::*;
use bevy::window::PrimaryWindow;
use bevy_egui::{EguiContexts, EguiPrimaryContextPass, egui};

use crate::arc_core::*;
use crate::camera::EditorCamera;
use crate::gizmo_3d::{GizmoState, gizmo_system};
use crate::props::SceneObject;

const MARQUEE_THRESHOLD: f32 = 4.0;

/// Soft-deleted object (hidden, kept so undo can bring it back).
#[derive(Component)]
pub struct Deleted;

/// Transform scale at spawn; AABB half extents are expressed at this scale.
#[derive(Component, Clone, Copy)]
pub struct SpawnScale(pub Vec3);

#[derive(Resource, Default)]
pub struct EditorSelection {
    pub primary: Option<Entity>,
    pub selected: HashSet<Entity>,
    pub marquee: Option<(Vec2, Vec2)>,
    press: Option<Vec2>,
    hit_object: bool,
}

impl EditorSelection {
    pub fn clear(&mut self) {
        self.primary = None;
        self.selected.clear();
    }
    pub fn set_one(&mut self, e: Entity) {
        self.selected.clear();
        self.selected.insert(e);
        self.primary = Some(e);
    }
    fn set_all(&mut self, set: HashSet<Entity>) {
        if !self.primary.is_some_and(|p| set.contains(&p)) {
            self.primary = set.iter().copied().min_by_key(|e| e.to_bits());
        }
        self.selected = set;
    }
}

#[derive(Default, Reflect, GizmoConfigGroup)]
pub struct SelectionGizmos;

/// Oriented box of an object: (centre, half extents, rotation). The pivot sits on the object's base.
pub fn object_box(tf: &Transform, so: &SceneObject, base: Option<&SpawnScale>) -> (Vec3, Vec3, Quat) {
    let ratio = base.map_or(Vec3::ONE, |b| tf.scale / b.0.max(Vec3::splat(1e-4)));
    let half = so.aabb_half_extents * ratio.abs();
    (tf.translation + tf.rotation * Vec3::new(0.0, half.y, 0.0), half, tf.rotation)
}

/// 12 wireframe edges of an oriented box.
pub fn draw_box<T: GizmoConfigGroup>(g: &mut Gizmos<T>, c: Vec3, h: Vec3, q: Quat, color: Color) {
    let corner = |s: u32| c + q * (Vec3::new(if s & 1 == 0 { -1.0 } else { 1.0 }, if s & 2 == 0 { -1.0 } else { 1.0 }, if s & 4 == 0 { -1.0 } else { 1.0 }) * h);
    for s in 0..8u32 {
        for bit in [1u32, 2, 4] {
            if s & bit == 0 {
                g.line(corner(s), corner(s | bit), color);
            }
        }
    }
}

pub struct SelectionPlugin;

impl Plugin for SelectionPlugin {
    fn build(&self, app: &mut App) {
        app.add_plugins(MeshPickingPlugin)
            .insert_resource(MeshPickingSettings { require_markers: true, ..default() })
            .init_resource::<EditorSelection>()
            .init_gizmo_group::<SelectionGizmos>()
            .add_observer(on_click)
            .add_systems(Startup, |mut store: ResMut<GizmoConfigStore>| {
                let (cfg, _) = store.config_mut::<SelectionGizmos>();
                cfg.depth_bias = -0.2;
                cfg.line.width = 3.0;
            })
            .add_systems(Update, (mark_pickable, init_spawn_scale, prune_selection, env_select, selection_input.after(gizmo_system), draw_selection).chain())
            .add_systems(EguiPrimaryContextPass, draw_marquee);
    }
}

fn mark_pickable(
    mut commands: Commands,
    new: Query<Entity, Added<Mesh3d>>,
    parents: Query<&ChildOf>,
    objs: Query<(), With<SceneObject>>,
    cams: Query<Entity, (With<EditorCamera>, Without<MeshPickingCamera>)>,
) {
    for c in &cams {
        commands.entity(c).insert(MeshPickingCamera);
    }
    for e in &new {
        let mut cur = e;
        loop {
            if objs.contains(cur) {
                commands.entity(e).insert(Pickable::default());
                break;
            }
            match parents.get(cur) {
                Ok(p) => cur = p.parent(),
                Err(_) => break,
            }
        }
    }
}

fn init_spawn_scale(mut commands: Commands, q: Query<(Entity, &Transform), (With<SceneObject>, Without<SpawnScale>)>) {
    for (e, tf) in &q {
        commands.entity(e).insert(SpawnScale(tf.scale));
    }
}

pub fn prune_selection(mut sel: ResMut<EditorSelection>, alive: Query<(), (With<SceneObject>, Without<Deleted>)>) {
    if sel.selected.iter().any(|e| !alive.contains(*e)) {
        sel.selected.retain(|e| alive.contains(*e));
    }
    if sel.primary.is_some_and(|p| !sel.selected.contains(&p)) {
        sel.primary = sel.selected.iter().copied().min_by_key(|e| e.to_bits());
    }
}

/// Dev aid: `ARC_SELECT=<Name>` selects the first object with that name once it exists.
fn env_select(mut sel: ResMut<EditorSelection>, mut done: Local<bool>, q: Query<(Entity, &SceneObject), Without<Deleted>>) {
    if *done {
        return;
    }
    let Ok(name) = std::env::var("ARC_SELECT") else {
        *done = true;
        return;
    };
    if let Some((e, _)) = q.iter().find(|(_, so)| so.name == name) {
        sel.set_one(e);
        *done = true;
    }
}

#[allow(clippy::too_many_arguments)]
fn on_click(
    mut ev: On<PointerClick>,
    keys: Res<ButtonInput<KeyCode>>,
    mut sel: ResMut<EditorSelection>,
    gizmo: Res<GizmoState>,
    objs: Query<(), (With<SceneObject>, Without<Deleted>)>,
    parents: Query<&ChildOf>,
    window: Single<&Window, With<PrimaryWindow>>,
    mut egui: EguiContexts,
) {
    ev.propagate(false);
    let blocked = egui.ctx_mut().map(|c| c.is_pointer_over_egui()).unwrap_or(false);
    let (Some(p0), Some(cur)) = (sel.press, window.cursor_position()) else { return };
    if ev.button != PointerButton::Primary || blocked || gizmo.busy() || p0.distance(cur) > MARQUEE_THRESHOLD {
        return;
    }
    let mut e = ev.original_event_target();
    let root = loop {
        if objs.contains(e) {
            break Some(e);
        }
        match parents.get(e) {
            Ok(p) => e = p.parent(),
            Err(_) => break None,
        }
    };
    let Some(root) = root else { return };
    sel.hit_object = true;
    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
    let ctrl = keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]);
    if shift || ctrl {
        if sel.selected.contains(&root) {
            sel.selected.remove(&root);
            if sel.primary == Some(root) {
                sel.primary = sel.selected.iter().copied().min_by_key(|e| e.to_bits());
            }
        } else {
            sel.selected.insert(root);
            sel.primary = Some(root);
        }
    } else {
        sel.set_one(root);
    }
}

#[allow(clippy::too_many_arguments)]
pub fn selection_input(
    mouse: Res<ButtonInput<MouseButton>>,
    keys: Res<ButtonInput<KeyCode>>,
    window: Single<&Window, With<PrimaryWindow>>,
    mut sel: ResMut<EditorSelection>,
    gizmo: Res<GizmoState>,
    mut egui: EguiContexts,
    cam: Single<(&Camera, &GlobalTransform), With<EditorCamera>>,
    objs: Query<(Entity, &Transform, &SceneObject, Option<&SpawnScale>), Without<Deleted>>,
) {
    let blocked = egui.ctx_mut().map(|c| c.is_pointer_over_egui() || c.egui_wants_pointer_input()).unwrap_or(false);
    let alt = keys.any_pressed([KeyCode::AltLeft, KeyCode::AltRight]);
    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
    let ctrl = keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]);
    let cursor = window.cursor_position();

    if mouse.just_pressed(MouseButton::Left) && !alt && !blocked && !gizmo.busy() {
        sel.press = cursor;
        sel.hit_object = false;
    }
    if mouse.pressed(MouseButton::Left) {
        if let (Some(p0), Some(c)) = (sel.press, cursor) {
            if p0.distance(c) > MARQUEE_THRESHOLD || sel.marquee.is_some() {
                sel.marquee = Some((p0, c));
            }
        }
    }
    if !mouse.just_released(MouseButton::Left) {
        return;
    }
    let marquee = sel.marquee.take();
    if sel.press.take().is_none() {
        return;
    }
    if let Some((a, b)) = marquee {
        let rect = normalize_rect(a, b);
        let (camera, gtf) = *cam;
        let inside: HashSet<Entity> = objs
            .iter()
            .filter(|(_, tf, so, base)| {
                let (c, _, _) = object_box(tf, so, *base);
                camera.world_to_viewport(gtf, c).is_ok_and(|p| rect_contains(rect, p))
            })
            .map(|(e, ..)| e)
            .collect();
        let next = combine_selection(&sel.selected, &inside, shift, ctrl);
        sel.set_all(next);
    } else if !sel.hit_object && !shift && !ctrl {
        sel.clear();
    }
}

fn draw_selection(sel: Res<EditorSelection>, objs: Query<(&Transform, &SceneObject, Option<&SpawnScale>), Without<Deleted>>, mut gizmos: Gizmos<SelectionGizmos>) {
    for e in &sel.selected {
        let Ok((tf, so, base)) = objs.get(*e) else { continue };
        let (c, h, q) = object_box(tf, so, base);
        let (dim, bright) = if sel.primary == Some(*e) {
            (Color::linear_rgb(0.15, 0.7, 1.0), Color::linear_rgb(0.5, 3.0, 4.5))
        } else {
            (Color::linear_rgb(0.1, 0.4, 0.6), Color::linear_rgb(0.3, 1.8, 2.8))
        };
        draw_box(&mut gizmos, c, h, q, dim);
        for s in 0..8u32 {
            let sg = Vec3::new(if s & 1 == 0 { -1.0 } else { 1.0 }, if s & 2 == 0 { -1.0 } else { 1.0 }, if s & 4 == 0 { -1.0 } else { 1.0 });
            let corner = c + q * (sg * h);
            for axis in 0..3 {
                let mut dir = Vec3::ZERO;
                dir[axis] = -sg[axis];
                let len = (h[axis] * 0.5).min(1.6);
                gizmos.line(corner, corner + q * dir * len, bright);
            }
        }
    }
}

fn draw_marquee(mut contexts: EguiContexts, sel: Res<EditorSelection>) {
    let Some((a, b)) = sel.marquee else { return };
    let Ok(ctx) = contexts.ctx_mut() else { return };
    let painter = ctx.layer_painter(egui::LayerId::new(egui::Order::Foreground, egui::Id::new("marquee")));
    let rect = egui::Rect::from_two_pos(egui::pos2(a.x, a.y), egui::pos2(b.x, b.y));
    painter.rect_filled(rect, 0.0, egui::Color32::from_rgba_unmultiplied(80, 170, 255, 40));
    painter.rect_stroke(rect, 0.0, egui::Stroke::new(1.5, egui::Color32::from_rgb(120, 200, 255)), egui::StrokeKind::Inside);
}
//! Editor camera (doc 01): orbit, depth pan, exponential zoom, fly mode, focus.

use bevy::input::mouse::{AccumulatedMouseMotion, AccumulatedMouseScroll, MouseScrollUnit};
use bevy::prelude::*;
use bevy::window::PrimaryWindow;
use bevy_egui::EguiContexts;

use crate::scene::TerrainGrid;

const K_ROT: f32 = 0.0052;
const ZOOM_RATE: f32 = 0.15;
const PITCH_LIM: f32 = 89.0 * std::f32::consts::PI / 180.0;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Reflect)]
pub enum CamMode {
    Orbit,
    Pan,
    Fly,
}

#[derive(Component, Reflect)]
#[reflect(Component)]
pub struct EditorCamera {
    pub yaw: f32,
    pub pitch: f32,
    pub pivot: Vec3,
    pub distance: f32,
    /// Base fly speed v0 (m/s).
    pub fly_speed: f32,
    /// Shift ramp: a = accel + 1.
    pub fly_accel: f32,
    pub v_target: f32,
    pub vel: Vec3,
    pub mode: Option<CamMode>,
    pub focus: Option<(Vec3, f32)>,
}

impl Default for EditorCamera {
    fn default() -> Self {
        Self { yaw: 0.0, pitch: 0.3, pivot: Vec3::ZERO, distance: 30.0, fly_speed: 9.0, fly_accel: 1.5, v_target: 9.0, vel: Vec3::ZERO, mode: None, focus: None }
    }
}

impl EditorCamera {
    pub fn forward(&self) -> Vec3 {
        let (cp, sp) = (self.pitch.cos(), self.pitch.sin());
        Vec3::new(cp * self.yaw.sin(), -sp, cp * self.yaw.cos())
    }
    pub fn eye(&self) -> Vec3 {
        self.pivot - self.forward() * self.distance
    }
    /// Focus on a bounding sphere: distance = max(radius / sin(fov/2), 2).
    pub fn focus_on(&mut self, center: Vec3, radius: f32, fov_y: f32) {
        self.focus = Some((center, (radius / (fov_y * 0.5).sin()).max(2.0)));
    }
}

pub struct EditorCameraPlugin;

impl Plugin for EditorCameraPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(Update, editor_camera_system);
    }
}

#[allow(clippy::too_many_arguments)]
fn editor_camera_system(
    time: Res<Time>,
    mouse: Res<ButtonInput<MouseButton>>,
    keys: Res<ButtonInput<KeyCode>>,
    motion: Res<AccumulatedMouseMotion>,
    scroll: Res<AccumulatedMouseScroll>,
    terrain: Option<Res<TerrainGrid>>,
    mut egui: EguiContexts,
    window: Single<&Window, With<PrimaryWindow>>,
    mut cam: Single<(&mut EditorCamera, &mut Transform, &Camera, &Projection, &GlobalTransform)>,
) {
    let (ctrl, tf, camera, proj, gtf) = &mut *cam;
    let dt = time.delta_secs().min(0.1);
    let fov_y = if let Projection::Perspective(p) = proj { p.fov } else { 1.0 };
    let blocked = egui.ctx_mut().map(|c| c.egui_wants_pointer_input() || c.is_pointer_over_egui()).unwrap_or(false);
    let alt = keys.any_pressed([KeyCode::AltLeft, KeyCode::AltRight]);
    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
    let d = motion.delta;

    // mode selection: only starts when the pointer is not over egui; ends on release
    if !blocked {
        if mouse.just_pressed(MouseButton::Right) {
            ctrl.mode = Some(CamMode::Fly);
            ctrl.v_target = ctrl.fly_speed;
            ctrl.vel = Vec3::ZERO;
        } else if mouse.just_pressed(MouseButton::Middle) {
            ctrl.mode = Some(if shift { CamMode::Pan } else { CamMode::Orbit });
        } else if mouse.just_pressed(MouseButton::Left) && alt {
            ctrl.mode = Some(if shift { CamMode::Pan } else { CamMode::Orbit });
        }
    }
    let held = match ctrl.mode {
        Some(CamMode::Fly) => mouse.pressed(MouseButton::Right),
        Some(_) => mouse.pressed(MouseButton::Middle) || mouse.pressed(MouseButton::Left),
        None => false,
    };
    if !held {
        if ctrl.mode == Some(CamMode::Fly) {
            ctrl.pivot = ctrl.eye() + ctrl.forward() * ctrl.distance; // pivot carried along with the eye
        }
        ctrl.mode = None;
        ctrl.vel = Vec3::ZERO;
    }

    let fwd = ctrl.forward();
    let right = fwd.cross(Vec3::Y).normalize_or_zero();
    let up = right.cross(fwd);

    match ctrl.mode {
        Some(CamMode::Orbit) => {
            ctrl.yaw -= d.x * K_ROT;
            ctrl.pitch = (ctrl.pitch - d.y * K_ROT).clamp(-PITCH_LIM, PITCH_LIM);
        }
        Some(CamMode::Pan) => {
            let u = 2.0 * ctrl.distance * (fov_y * 0.5).tan() / window.height();
            ctrl.pivot += (-right * d.x + up * d.y) * u;
        }
        Some(CamMode::Fly) => {
            let eye = ctrl.eye();
            ctrl.yaw -= d.x * K_ROT;
            ctrl.pitch = (ctrl.pitch + d.y * K_ROT).clamp(-PITCH_LIM, PITCH_LIM); // FPS look: mouse up = look up
            let (fwd, right) = (ctrl.forward(), ctrl.forward().cross(Vec3::Y).normalize_or_zero());
            let ax = |p: KeyCode, n: KeyCode| keys.pressed(p) as i32 as f32 - keys.pressed(n) as i32 as f32;
            let wish = (fwd * ax(KeyCode::KeyW, KeyCode::KeyS) + right * ax(KeyCode::KeyD, KeyCode::KeyA) + Vec3::Y * ax(KeyCode::KeyE, KeyCode::KeyQ)).normalize_or_zero();
            if scroll.delta.y != 0.0 {
                ctrl.fly_speed = (ctrl.fly_speed * (scroll.delta.y * 0.1).exp()).clamp(0.1, 500.0);
            }
            ctrl.v_target = if shift { (ctrl.v_target * (ctrl.fly_accel + 1.0).powf(dt)).min(500.0) } else { ctrl.fly_speed };
            let target = wish * ctrl.v_target;
            ctrl.vel = ctrl.vel.lerp(target, 1.0 - (-dt / 0.08).exp());
            let new_eye = eye + ctrl.vel * dt;
            ctrl.pivot = new_eye + ctrl.forward() * ctrl.distance;
        }
        None => {}
    }

    // zoom (wheel), cursor-directed when the cursor ray hits the terrain
    if ctrl.mode != Some(CamMode::Fly) && !blocked && scroll.delta.y != 0.0 {
        let notches = match scroll.unit {
            MouseScrollUnit::Line => scroll.delta.y,
            MouseScrollUnit::Pixel => scroll.delta.y / 40.0,
        } * if shift { 3.0 } else { 1.0 };
        let hit = window
            .cursor_position()
            .and_then(|c| camera.viewport_to_world(*gtf, c).ok())
            .and_then(|ray| terrain.as_ref().and_then(|t| t.0.raycast(ray.origin, *ray.direction)));
        let eye = ctrl.eye();
        match hit {
            Some(p) => {
                let eye2 = eye + (p - eye) * (1.0 - (-notches * ZOOM_RATE).exp());
                ctrl.distance = (p - eye2).length().clamp(0.1, 5000.0);
                ctrl.pivot = eye2 + ctrl.forward() * ctrl.distance;
            }
            None => ctrl.distance = (ctrl.distance * (-notches * ZOOM_RATE).exp()).clamp(0.1, 5000.0),
        }
    }

    // focus (F): selection AABB is not available yet, so focus the point under the cursor (or current pivot)
    if keys.just_pressed(KeyCode::KeyF) && !blocked {
        let hit = window
            .cursor_position()
            .and_then(|c| camera.viewport_to_world(*gtf, c).ok())
            .and_then(|ray| terrain.as_ref().and_then(|t| t.0.raycast(ray.origin, *ray.direction)));
        let c = hit.unwrap_or(ctrl.pivot);
        ctrl.focus_on(c, 4.0, fov_y);
    }
    if let Some((tp, td)) = ctrl.focus {
        let s = 1.0 - (-dt / 0.12).exp();
        ctrl.pivot = ctrl.pivot.lerp(tp, s);
        ctrl.distance += (td - ctrl.distance) * s;
        if ctrl.pivot.distance(tp) < 1e-3 && (ctrl.distance - td).abs() < 1e-3 {
            ctrl.focus = None;
        }
    }

    **tf = Transform::from_translation(ctrl.eye()).looking_at(ctrl.pivot, Vec3::Y);
}
