1	//! Minimal egui panel: world presets, atmosphere toggles, transactional undo/redo.
2	
3	use bevy::prelude::*;
4	use bevy_egui::{EguiContexts, EguiPrimaryContextPass, egui};
5	
6	use crate::arc_core::*;
