11	
12	impl Plugin for UiPlugin {
13	    fn build(&self, app: &mut App) {
14	        app.add_systems(EguiPrimaryContextPass, studio_ui_system);
15	    }
16	}
17	
18	fn studio_ui_system(mut contexts: EguiContexts, mut spec: ResMut<WorldSpec>, mut hist: ResMut<UndoHistory<WorldSpec>>, mut gz: ResMut<GizmoState>, sel: Res<EditorSelection>) {
19	    let Ok(ctx) = contexts.ctx_mut() else { return };
20	    let mut viewport_ui = egui::Ui::new(ctx.clone(), "viewport".into(), egui::UiBuilder::new().layer_id(egui::LayerId::background()).max_rect(ctx.viewport_rect()));
21	    egui::Panel::left("studio_panel").default_size(250.0).show(&mut viewport_ui, |ui| {
22	        ui.heading("Bevy ArcStudio");
23	        ui.horizontal(|ui| {
24	            if ui.add_enabled(hist.undo_len() > 0, egui::Button::new("Undo")).clicked() {
25	                if let Some(s) = hist.undo() {
26	                    *spec = s;
27	                }
28	            }
29	            if ui.add_enabled(hist.redo_len() > 0, egui::Button::new("Redo")).clicked() {
30	                if let Some(s) = hist.redo() {
31	                    *spec = s;
32	                }
33	            }
34	            ui.label(format!("{}/{}", hist.undo_len(), hist.redo_len()));
35	        });
36	        ui.separator();
37	        for (name, p) in [
38	            ("Misty Dusk Lake", WorldPreset::MistyDuskLake),
39	            ("Sunny Alpine Noon", WorldPreset::SunnyAlpineNoon),
40	            ("Midnight Campfire", WorldPreset::MidnightCampfire),
41	            ("Golden Autumn Dawn", WorldPreset::GoldenAutumnDawn),
42	        ] {
43	            if ui.button(name).clicked() {
44	                let before = spec.clone();
45	                let mut next = before.clone();
46	                let preset = WorldSpec::from_preset(p);
47	                // atmosphere only: terrain stays as generated
48	                next.time_of_day = preset.time_of_day;
49	                next.fog_color = preset.fog_color;
50	                next.fog_density = preset.fog_density;
51	                next.sun_intensity = preset.sun_intensity;
52	                next.god_rays = preset.god_rays;
53	                hist.record(name, before, next.clone());
54	                *spec = next;
55	            }
56	        }
57	        ui.separator();
58	
59	        // slider drag → Begin → UpdatePreview* → Commit (one undo entry)
60	        let mut t = spec.time_of_day;
61	        let r = ui.add(egui::Slider::new(&mut t, 0.0..=24.0).text("time of day"));
62	        if r.drag_started() || (r.changed() && !hist.is_open() && !r.dragged()) {
63	            hist.begin("time_of_day", spec.clone());
64	        }
65	        if r.changed() {
66	            spec.time_of_day = t;
67	            let s = spec.clone();
68	            hist.update_preview(s);
69	        }
70	        if r.drag_stopped() || (r.changed() && !r.dragged() && hist.is_open()) {
71	            let s = spec.clone();
72	            hist.commit(s);
73	        }
74	
75	        let mut s = spec.clone();
76	        let mut dirty = false;
77	        for (label, v) in [
78	            ("auto sun (advance time)", &mut s.auto_sun),
79	            ("fog", &mut s.fog_enabled),
80	            ("god rays", &mut s.god_rays),
81	            ("bloom", &mut s.bloom),
82	            ("reflections", &mut s.reflections),
83	            ("shadows", &mut s.shadows),
84	        ] {
85	            dirty |= ui.checkbox(v, label).changed();
86	        }
87	        let mut sun = s.sun_intensity;
88	        let r = ui.add(egui::Slider::new(&mut sun, 0.0..=2.0).text("sun intensity"));
89	        if r.changed() {
90	            s.sun_intensity = sun;
91	            dirty = true;
92	        }
93	        if dirty {
94	            hist.record("atmosphere", spec.clone(), s.clone());
95	            *spec = s;
96	        }
97	        ui.separator();
98	        ui.horizontal(|ui| {
99	            for (label, m) in [("Q Select", GizmoMode::Select), ("W Move", GizmoMode::Move), ("E Rotate", GizmoMode::Rotate), ("R Scale", GizmoMode::Scale)] {
100	                ui.selectable_value(&mut gz.mode, m, label);
101	            }
102	        });
103	        ui.horizontal(|ui| {
104	            ui.selectable_value(&mut gz.space, GizmoSpace::World, "World");
105	            ui.selectable_value(&mut gz.space, GizmoSpace::Local, "Local (X)");
106	        });
107	        ui.checkbox(&mut gz.snap_ground, "Snap to Ground (Shift)");
108	        ui.checkbox(&mut gz.align_normal, "Align to Normal");
109	        ui.label(format!("selected: {}", sel.selected.len()));
110	        ui.small("Ctrl+D duplicate · Del delete · Ctrl+Z/Y undo/redo (objects) · Ctrl drag = snap · Esc cancel");
111	        ui.separator();
112	        ui.small("RMB+WASD/QE fly · MMB/Alt+LMB orbit · Shift+MMB pan · wheel zoom · F focus");
113	    });
114	}
