1	//! Startup scene: sun/moon, fog volume and editor camera (terrain, water and props live in their own modules).
2	
3	use bevy::light::atmosphere::ScatteringMedium;
4	use bevy::light::{Atmosphere, FogVolume, SunDisk, VolumetricLight};
5	use bevy::prelude::*;
6	
7	use crate::arc_core::*;
8	use crate::camera::EditorCamera;
9	use crate::lighting::{self, Moon, Sun};
10	pub use crate::terrain_render::TerrainGrid;
11	
12	pub struct ScenePlugin;
13	
14	impl Plugin for ScenePlugin {
15	    fn build(&self, app: &mut App) {
16	        app.add_systems(PostStartup, setup_scene);
17	    }
18	}
19	
20	fn setup_scene(
21	    mut commands: Commands,
22	    spec: Res<WorldSpec>,
23	    grid: Res<TerrainGrid>,
24	    mut media: ResMut<Assets<ScatteringMedium>>,
25	) {
26	    let grid = &grid.0;
27	    commands.spawn((
28	        Name::new("Sun"),
29	        Sun,
30	        DirectionalLight { shadow_maps_enabled: spec.shadows, illuminance: 100_000.0, ..default() },
31	        SunDisk::EARTH,
32	        VolumetricLight,
33	        lighting::cascades(),
34	        Transform::default().looking_to(Vec3::NEG_Y, Vec3::X),
35	    ));
36	    commands.spawn((
37	        Name::new("Moon"),
38	        Moon,
39	        DirectionalLight { color: Color::srgb(0.55, 0.65, 1.0), illuminance: 0.0, shadow_maps_enabled: false, ..default() },
40	        Transform::default().looking_to(Vec3::NEG_Y, Vec3::X),
41	    ));
42	    commands.spawn((
43	        Name::new("FogVolume"),
44	        FogVolume { density_factor: 0.02, scattering: 0.4, absorption: 0.05, ..default() },
45	        Transform::from_xyz(0.0, 40.0, 0.0).with_scale(Vec3::new(grid.size, 120.0, grid.size)),
46	    ));
47	
48	    let camp = Vec3::new(spec.camp_center[0], grid.sample_height(spec.camp_center[0], spec.camp_center[1]), spec.camp_center[1]);
49	    let mut cam = EditorCamera { pivot: camp + Vec3::new(-14.0, 2.0, 8.0), distance: 34.0, yaw: -1.2, pitch: 0.14, ..default() };
50	    // dev aid: ARC_CAM="px,py,pz,yaw,pitch,distance"
51	    if let Some(v) = std::env::var("ARC_CAM").ok().map(|s| s.split(',').filter_map(|t| t.trim().parse::<f32>().ok()).collect::<Vec<_>>()).filter(|v| v.len() == 6) {
52	        (cam.pivot, cam.yaw, cam.pitch, cam.distance) = (Vec3::new(v[0], v[1], v[2]), v[3], v[4], v[5]);
53	        // keep the eye above the terrain
54	        let fwd = Vec3::new(cam.pitch.cos() * cam.yaw.sin(), -cam.pitch.sin(), cam.pitch.cos() * cam.yaw.cos());
55	        let eye = cam.pivot - fwd * cam.distance;
56	        let min_y = grid.sample_height(eye.x, eye.z) + 3.0;
57	        info!("ARC_CAM eye {eye:?}, ground {:.1}", min_y - 3.0);
58	        cam.pivot.y += (min_y - eye.y).max(0.0);
59	    }
60	    let medium = media.add(ScatteringMedium::earth(256, 256));
61	    let atmosphere = Atmosphere::earth(medium);
62	    commands.spawn((Name::new("Planet"), Transform::from_xyz(0.0, -atmosphere.inner_radius, 0.0), atmosphere));
63	    commands.spawn((
64	        Name::new("EditorCamera"),
65	        Camera3d::default(),
66	        cam,
67	        Transform::default(),
68	        lighting::camera_stack(&spec),
69	    ));
70	}
