59	/// Oriented box of an object: (centre, half extents, rotation). The pivot sits on the object's base.
60	pub fn object_box(tf: &Transform, so: &SceneObject, base: Option<&SpawnScale>) -> (Vec3, Vec3, Quat) {
61	    let ratio = base.map_or(Vec3::ONE, |b| tf.scale / b.0.max(Vec3::splat(1e-4)));
62	    let half = so.aabb_half_extents * ratio.abs();
63	    (tf.translation + tf.rotation * Vec3::new(0.0, half.y, 0.0), half, tf.rotation)
64	}
65	
66	/// 12 wireframe edges of an oriented box.
67	pub fn draw_box<T: GizmoConfigGroup>(g: &mut Gizmos<T>, c: Vec3, h: Vec3, q: Quat, color: Color) {
68	    let corner = |s: u32| c + q * (Vec3::new(if s & 1 == 0 { -1.0 } else { 1.0 }, if s & 2 == 0 { -1.0 } else { 1.0 }, if s & 4 == 0 { -1.0 } else { 1.0 }) * h);
69	    for s in 0..8u32 {
70	        for bit in [1u32, 2, 4] {
71	            if s & bit == 0 {
72	                g.line(corner(s), corner(s | bit), color);
73	            }
74	        }
75	    }
76	}
