97	fn mark_pickable(
98	    mut commands: Commands,
99	    new: Query<Entity, Added<Mesh3d>>,
100	    parents: Query<&ChildOf>,
101	    objs: Query<(), With<SceneObject>>,
102	    cams: Query<Entity, (With<EditorCamera>, Without<MeshPickingCamera>)>,
103	) {
104	    for c in &cams {
105	        commands.entity(c).insert(MeshPickingCamera);
106	    }
107	    for e in &new {
108	        let mut cur = e;
109	        loop {
110	            if objs.contains(cur) {
111	                commands.entity(e).insert(Pickable::default());
112	                break;
113	            }
114	            match parents.get(cur) {
115	                Ok(p) => cur = p.parent(),
116	                Err(_) => break,
117	            }
118	        }
119	    }
120	}
