128	pub fn prune_selection(mut sel: ResMut<EditorSelection>, alive: Query<(), (With<SceneObject>, Without<Deleted>)>) {
129	    if sel.selected.iter().any(|e| !alive.contains(*e)) {
130	        sel.selected.retain(|e| alive.contains(*e));
131	    }
132	    if sel.primary.is_some_and(|p| !sel.selected.contains(&p)) {
133	        sel.primary = sel.selected.iter().copied().min_by_key(|e| e.to_bits());
