137	/// Dev aid: `ARC_SELECT=<Name>` selects the first object with that name once it exists.
138	fn env_select(mut sel: ResMut<EditorSelection>, mut done: Local<bool>, q: Query<(Entity, &SceneObject), Without<Deleted>>) {
139	    if *done {
140	        return;
141	    }
142	    let Ok(name) = std::env::var("ARC_SELECT") else {
143	        *done = true;
144	        return;
145	    };
146	    if let Some((e, _)) = q.iter().find(|(_, so)| so.name == name) {
