152	#[allow(clippy::too_many_arguments)]
153	fn on_click(
154	    mut ev: On<PointerClick>,
155	    keys: Res<ButtonInput<KeyCode>>,
156	    mut sel: ResMut<EditorSelection>,
157	    gizmo: Res<GizmoState>,
158	    objs: Query<(), (With<SceneObject>, Without<Deleted>)>,
159	    parents: Query<&ChildOf>,
160	    window: Single<&Window, With<PrimaryWindow>>,
161	    mut egui: EguiContexts,
162	) {
163	    ev.propagate(false);
164	    let blocked = egui.ctx_mut().map(|c| c.is_pointer_over_egui()).unwrap_or(false);
165	    let (Some(p0), Some(cur)) = (sel.press, window.cursor_position()) else { return };
166	    if ev.button != PointerButton::Primary || blocked || gizmo.busy() || p0.distance(cur) > MARQUEE_THRESHOLD {
167	        return;
168	    }
169	    let mut e = ev.original_event_target();
170	    let root = loop {
171	        if objs.contains(e) {
172	            break Some(e);
173	        }
174	        match parents.get(e) {
175	            Ok(p) => e = p.parent(),
176	            Err(_) => break None,
177	        }
178	    };
179	    let Some(root) = root else { return };
180	    sel.hit_object = true;
181	    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
182	    let ctrl = keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]);
183	    if shift || ctrl {
184	        if sel.selected.contains(&root) {
185	            sel.selected.remove(&root);
186	            if sel.primary == Some(root) {
187	                sel.primary = sel.selected.iter().copied().min_by_key(|e| e.to_bits());
188	            }
189	        } else {
190	            sel.selected.insert(root);
191	            sel.primary = Some(root);
192	        }
193	    } else {
194	        sel.set_one(root);
195	    }
196	}
197	
198	#[allow(clippy::too_many_arguments)]
199	pub fn selection_input(
200	    mouse: Res<ButtonInput<MouseButton>>,
201	    keys: Res<ButtonInput<KeyCode>>,
202	    window: Single<&Window, With<PrimaryWindow>>,
203	    mut sel: ResMut<EditorSelection>,
204	    gizmo: Res<GizmoState>,
205	    mut egui: EguiContexts,
206	    cam: Single<(&Camera, &GlobalTransform), With<EditorCamera>>,
207	    objs: Query<(Entity, &Transform, &SceneObject, Option<&SpawnScale>), Without<Deleted>>,
208	) {
209	    let blocked = egui.ctx_mut().map(|c| c.is_pointer_over_egui() || c.egui_wants_pointer_input()).unwrap_or(false);
210	    let alt = keys.any_pressed([KeyCode::AltLeft, KeyCode::AltRight]);
211	    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
212	    let ctrl = keys.any_pressed([KeyCode::ControlLeft, KeyCode::ControlRight]);
213	    let cursor = window.cursor_position();
214	
215	    if mouse.just_pressed(MouseButton::Left) && !alt && !blocked && !gizmo.busy() {
216	        sel.press = cursor;
217	        sel.hit_object = false;
218	    }
219	    if mouse.pressed(MouseButton::Left) {
220	        if let (Some(p0), Some(c)) = (sel.press, cursor) {
221	            if p0.distance(c) > MARQUEE_THRESHOLD || sel.marquee.is_some() {
222	                sel.marquee = Some((p0, c));
223	            }
224	        }
225	    }
226	    if !mouse.just_released(MouseButton::Left) {
227	        return;
228	    }
229	    let marquee = sel.marquee.take();
230	    if sel.press.take().is_none() {
231	        return;
232	    }
233	    if let Some((a, b)) = marquee {
234	        let rect = normalize_rect(a, b);
235	        let (camera, gtf) = *cam;
236	        let inside: HashSet<Entity> = objs
237	            .iter()
238	            .filter(|(_, tf, so, base)| {
239	                let (c, _, _) = object_box(tf, so, *base);
240	                camera.world_to_viewport(gtf, c).is_ok_and(|p| rect_contains(rect, p))
241	            })
242	            .map(|(e, ..)| e)
243	            .collect();
244	        let next = combine_selection(&sel.selected, &inside, shift, ctrl);
245	        sel.set_all(next);
246	    } else if !sel.hit_object && !shift && !ctrl {
247	        sel.clear();
248	    }
249	}
250	
251	fn draw_selection(sel: Res<EditorSelection>, objs: Query<(&Transform, &SceneObject, Option<&SpawnScale>), Without<Deleted>>, mut gizmos: Gizmos<SelectionGizmos>) {
252	    for e in &sel.selected {
253	        let Ok((tf, so, base)) = objs.get(*e) else { continue };
254	        let (c, h, q) = object_box(tf, so, base);
255	        let (dim, bright) = if sel.primary == Some(*e) {
256	            (Color::linear_rgb(0.15, 0.7, 1.0), Color::linear_rgb(0.5, 3.0, 4.5))
257	        } else {
258	            (Color::linear_rgb(0.1, 0.4, 0.6), Color::linear_rgb(0.3, 1.8, 2.8))
259	        };
260	        draw_box(&mut gizmos, c, h, q, dim);
261	        for s in 0..8u32 {
262	            let sg = Vec3::new(if s & 1 == 0 { -1.0 } else { 1.0 }, if s & 2 == 0 { -1.0 } else { 1.0 }, if s & 4 == 0 { -1.0 } else { 1.0 });
263	            let corner = c + q * (sg * h);
264	            for axis in 0..3 {
265	                let mut dir = Vec3::ZERO;
266	                dir[axis] = -sg[axis];
267	                let len = (h[axis] * 0.5).min(1.6);
268	                gizmos.line(corner, corner + q * dir * len, bright);
269	            }
270	        }
271	    }
272	}
273	
274	fn draw_marquee(mut contexts: EguiContexts, sel: Res<EditorSelection>) {
275	    let Some((a, b)) = sel.marquee else { return };
276	    let Ok(ctx) = contexts.ctx_mut() else { return };
277	    let painter = ctx.layer_painter(egui::LayerId::new(egui::Order::Foreground, egui::Id::new("marquee")));
278	    let rect = egui::Rect::from_two_pos(egui::pos2(a.x, a.y), egui::pos2(b.x, b.y));
279	    painter.rect_filled(rect, 0.0, egui::Color32::from_rgba_unmultiplied(80, 170, 255, 40));
280	    painter.rect_stroke(rect, 0.0, egui::Stroke::new(1.5, egui::Color32::from_rgb(120, 200, 255)), egui::StrokeKind::Inside);
281	}
