30	            terrain: (
31	                s.seed,
32	                s.resolution,
33	                [s.size.to_bits(), s.base_height.to_bits(), s.mountain_height.to_bits(), s.max_height.to_bits(), s.noise_frequency.to_bits(), s.warp_amount.to_bits(), s.shore_foam.to_bits()],
34	                s.erosion_droplets,
