1	//! AAA atmosphere: physical sky, sun/moon cycle, volumetric fog, SSR, bloom, night fires.
2	
3	use bevy::camera::Exposure;
4	use bevy::core_pipeline::tonemapping::Tonemapping;
5	use bevy::light::{
6	    AtmosphereEnvironmentMapLight, CascadeShadowConfig, CascadeShadowConfigBuilder, DirectionalLightShadowMap, FogVolume, GlobalAmbientLight, VolumetricFog,
7	    VolumetricLight,
8	};
9	use bevy::pbr::{AtmosphereSettings, DistanceFog, FogFalloff, ScreenSpaceReflections};
10	use bevy::post_process::bloom::Bloom;
11	use bevy::prelude::*;
12	
13	use crate::arc_core::{QualityPreset, WorldSpec, smoothstep};
14	
15	#[derive(Component)]
16	pub struct Sun;
17	#[derive(Component)]
18	pub struct Moon;
19	/// Point light that is lit between dusk and dawn (19:30–06:30).
20	#[derive(Component, Clone)]
21	pub struct NightLight {
22	    pub base: f32,
23	}
24	
25	const SUN_AZIMUTH: f32 = 0.6;
26	const EV_DAY: f32 = 13.5;
27	const EV_NIGHT: f32 = 5.5;
28	
29	/// Unit vector pointing from the scene towards the sun.
30	pub fn sun_direction(t: f32) -> Vec3 {
31	    let a = (t - 6.0) / 24.0 * std::f32::consts::TAU;
32	    Vec3::new(a.cos() * SUN_AZIMUTH.cos(), a.sin(), a.cos() * SUN_AZIMUTH.sin()).normalize()
33	}
34	
35	/// 0 = night, 1 = full day (smooth through twilight).
36	pub fn daylight(t: f32) -> f32 {
37	    smoothstep(-0.12, 0.28, sun_direction(t).y)
38	}
39	
40	/// 1 when night lights should burn: 19:30 → 06:30 with 30 min fades.
41	pub fn night_factor(t: f32) -> f32 {
42	    let t = t.rem_euclid(24.0);
43	    if t >= 12.0 { smoothstep(19.25, 19.75, t) } else { 1.0 - smoothstep(6.25, 6.75, t) }
44	}
45	
46	pub fn cascades() -> CascadeShadowConfig {
47	    CascadeShadowConfigBuilder { num_cascades: 4, minimum_distance: 0.5, maximum_distance: 220.0, first_cascade_far_bound: 12.0, overlap_proportion: 0.3 }.build()
48	}
49	
50	fn fog_component(spec: &WorldSpec) -> DistanceFog {
51	    DistanceFog {
52	        color: Color::linear_rgb(spec.fog_color[0], spec.fog_color[1], spec.fog_color[2]),
53	        directional_light_color: Color::srgba(1.0, 0.75, 0.45, 0.4),
54	        directional_light_exponent: 30.0,
55	        falloff: FogFalloff::Exponential { density: spec.fog_density },
56	    }
57	}
58	
59	/// All render components on the 3D camera.
60	/// The `Atmosphere` is its own entity (planet centre in world space); cameras only carry settings.
61	pub fn camera_stack(spec: &WorldSpec) -> impl Bundle {
62	    (
63	        Msaa::Off,
64	        Tonemapping::TonyMcMapface,
65	        Exposure { ev100: EV_DAY },
66	        AtmosphereSettings::default(),
67	        AtmosphereEnvironmentMapLight::default(),
68	        (
69	            Bloom::NATURAL,
70	            ScreenSpaceReflections::default(),
71	            VolumetricFog { ambient_intensity: 0.0, step_count: 48, ..default() },
72	            fog_component(spec),
73	        ),
74	    )
75	}
76	
77	pub struct LightingPlugin;
78	
79	impl Plugin for LightingPlugin {
80	    fn build(&self, app: &mut App) {
81	        app.insert_resource(GlobalAmbientLight { color: Color::srgb(0.45, 0.55, 0.9), brightness: 0.0, ..default() })
82	            .insert_resource(DirectionalLightShadowMap { size: 4096 })
83	            .add_systems(Update, (advance_clock, apply_time_of_day, apply_toggles, flicker_night_lights).chain());
84	    }
85	}
86	
87	fn advance_clock(mut spec: ResMut<WorldSpec>, time: Res<Time>) {
88	    if spec.auto_sun {
89	        spec.time_of_day = (spec.time_of_day + time.delta_secs() * 0.15).rem_euclid(24.0);
90	    }
91	}
92	
93	#[allow(clippy::type_complexity)]
94	fn apply_time_of_day(
95	    spec: Res<WorldSpec>,
96	    mut sun: Query<(&mut Transform, &mut DirectionalLight), (With<Sun>, Without<Moon>)>,
97	    mut moon: Query<(&mut Transform, &mut DirectionalLight), (With<Moon>, Without<Sun>)>,
98	    mut cam: Query<(&mut Exposure, &mut DistanceFog)>,
99	    mut vol: Query<&mut FogVolume>,
100	    mut ambient: ResMut<GlobalAmbientLight>,
101	) {
102	    let t = spec.time_of_day;
103	    let dir = sun_direction(t);
104	    let d = daylight(t);
105	    let elev = dir.y;
106	    if let Ok((mut tf, mut l)) = sun.single_mut() {
107	        *tf = Transform::default().looking_to(-dir, Vec3::Y);
