1	//! Procedural prop forge (pines, boulders, reeds, grass, pier, campsite) + auto-loading of `assets/models/*.glb`.
2	
3	use std::f32::consts::{FRAC_PI_2, TAU};
4	
5	use bevy::asset::RenderAssetUsages;
6	use bevy::light::{NotShadowCaster, VolumetricLight};
7	use bevy::mesh::{Indices, PrimitiveTopology, VertexAttributeValues};
8	use bevy::prelude::*;
9	use noise::NoiseFn;
