60	    base_y: f32,
61	    yaw: f32,
62	}
63	
64	// ───────────────────────────── Resources ─────────────────────────────
65	
66	struct Palette {
67	    veg: Handle<StandardMaterial>,
68	    rock: Handle<StandardMaterial>,
69	    wood: Handle<StandardMaterial>,
70	    blade: Handle<StandardMaterial>,
71	    canvas: Handle<StandardMaterial>,
72	    lantern_glass: Handle<StandardMaterial>,
73	    flame: [Handle<StandardMaterial>; 3],
74	    ember: Handle<StandardMaterial>,
75	    spark: Handle<StandardMaterial>,
76	}
