78	#[derive(Resource)]
79	struct PropAssets {
80	    pines: Vec<Handle<Mesh>>,
81	    rocks: Vec<Handle<Mesh>>,
82	    grass: Vec<Handle<Mesh>>,
83	    reeds: Vec<Handle<Mesh>>,
84	    tent: Handle<Mesh>,
85	    flame_cone: Handle<Mesh>,
86	    spark_mesh: Handle<Mesh>,
87	    mats: Palette,
88	}
89	
90	/// `.glb` files discovered in `assets/models/`.
91	#[derive(Resource, Default)]
92	pub struct ModelLibrary {
93	    pub models: Vec<(String, Handle<WorldAsset>)>,
94	}
95	
96	pub struct PropsPlugin;
97	
98	impl Plugin for PropsPlugin {
99	    fn build(&self, app: &mut App) {
100	        app.register_type::<SceneObject>()
101	            .register_type::<ObjectCategory>()
102	            .init_resource::<ModelLibrary>()
103	            .add_systems(Startup, (build_assets, load_models).chain())
104	            .add_systems(Update, (sync_props, animate_flames, animate_sparks, animate_bobbing));
105	    }
106	}
107	
108	// ───────────────────────────── Mesh helpers ─────────────────────────────
109	
110	fn hash01(n: u32) -> f32 {
111	    let mut x = n.wrapping_mul(0x9E37_79B1) ^ 0x85EB_CA6B;
112	    x ^= x >> 15;
113	    x = x.wrapping_mul(0x2C1B_3C6D);
114	    x ^= x >> 12;
115	    x = x.wrapping_mul(0x297A_2D39);
116	    x ^= x >> 15;
117	    (x & 0xFFFFFF) as f32 / 0x1000000 as f32
118	}
119	
120	fn rgb(r: f32, g: f32, b: f32) -> [f32; 4] {
121	    [r, g, b, 1.0]
122	}
123	
124	fn mulc(c: [f32; 4], k: f32) -> [f32; 4] {
125	    [c[0] * k, c[1] * k, c[2] * k, c[3]]
126	}
127	
128	fn mixc(a: [f32; 4], b: [f32; 4], t: f32) -> [f32; 4] {
129	    let t = t.clamp(0.0, 1.0);
130	    [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, 1.0]
131	}
132	
133	fn cyl(r: f32, h: f32, res: u32) -> Mesh {
134	    Cylinder::new(r, h).mesh().resolution(res).into()
135	}
136	fn cone(r: f32, h: f32, res: u32) -> Mesh {
137	    Cone::new(r, h).mesh().resolution(res).into()
138	}
139	fn cube(x: f32, y: f32, z: f32) -> Mesh {
140	    Cuboid::new(x, y, z).into()
141	}
142	
143	/// Accumulates transformed, vertex-coloured primitives into one mesh.
144	#[derive(Default)]
145	struct MeshAcc {
146	    pos: Vec<[f32; 3]>,
147	    nrm: Vec<[f32; 3]>,
148	    col: Vec<[f32; 4]>,
149	    idx: Vec<u32>,
150	}
151	
152	impl MeshAcc {
153	    fn push(&mut self, mesh: &Mesh, tf: Transform, warp: impl Fn(Vec3) -> Vec3, color: impl Fn(Vec3, [f32; 4]) -> [f32; 4]) {
154	        let p = mesh.attribute(Mesh::ATTRIBUTE_POSITION).and_then(|a| a.as_float3()).expect("positions");
155	        let n = mesh.attribute(Mesh::ATTRIBUTE_NORMAL).and_then(|a| a.as_float3()).expect("normals");
156	        let c = match mesh.attribute(Mesh::ATTRIBUTE_COLOR) {
157	            Some(VertexAttributeValues::Float32x4(v)) => Some(v.as_slice()),
158	            _ => None,
159	        };
160	        let base = self.pos.len() as u32;
161	        for k in 0..p.len() {
162	            let lp = Vec3::from(p[k]);
163	            self.pos.push(tf.transform_point(warp(lp)).to_array());
164	            self.nrm.push((tf.rotation * (Vec3::from(n[k]) / tf.scale)).normalize_or_zero().to_array());
165	            self.col.push(color(lp, c.map_or([1.0; 4], |c| c[k])));
166	        }
167	        match mesh.indices() {
168	            Some(i) => self.idx.extend(i.iter().map(|i| base + i as u32)),
169	            None => self.idx.extend((0..p.len() as u32).map(|i| base + i)),
170	        }
171	    }
172	
173	    fn plain(&mut self, mesh: &Mesh, tf: Transform, col: [f32; 4]) {
174	        self.push(mesh, tf, |p| p, |_, _| col);
175	    }
176	
177	    fn build(self) -> Mesh {
178	        Mesh::new(PrimitiveTopology::TriangleList, RenderAssetUsages::default())
179	            .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, self.pos)
180	            .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, self.nrm)
181	            .with_inserted_attribute(Mesh::ATTRIBUTE_COLOR, self.col)
182	            .with_inserted_indices(Indices::U32(self.idx))
183	    }
184	}
185	
186	/// Five-tier pine: bark trunk + ragged needle tiers with per-variant tone and scale.
187	fn pine_mesh(variant: u32) -> Mesh {
188	    let mut acc = MeshAcc::default();
189	    let v = variant * 17 + 3;
190	    let bark = rgb(0.075 + 0.02 * hash01(v), 0.040, 0.022);
191	    acc.push(&cyl(0.26, 3.4, 8), Transform::from_xyz(0.0, 1.7, 0.0), |p| p * Vec3::new(1.0 - 0.35 * (p.y + 1.7) / 3.4, 1.0, 1.0 - 0.35 * (p.y + 1.7) / 3.4), |p, _| mulc(bark, 0.7 + 0.5 * (p.y + 1.7) / 3.4));
192	    let hue = hash01(v + 1);
193	    let dark = rgb(0.014 + 0.012 * hue, 0.075 + 0.04 * hue, 0.03);
194	    let light = rgb(0.045 + 0.03 * hue, 0.17 + 0.05 * hue, 0.05);
195	    for k in 0..5u32 {
196	        let t = k as f32 / 4.0;
197	        let radius = (2.15 - 1.35 * t) * (0.92 + 0.16 * hash01(v + 10 + k));
198	        let height = 2.6 - 0.8 * t;
199	        let base_y = 1.7 + k as f32 * 1.12;
200	        let tier_tone = 0.8 + 0.4 * hash01(v + 20 + k);
201	        let seed = (v + k) as f32;
202	        let h = height;
203	        acc.push(
204	            &cone(radius, height, 14),
205	            Transform::from_xyz(0.0, base_y + height * 0.5, 0.0).with_rotation(Quat::from_rotation_y(hash01(v + 30 + k) * TAU)),
206	            move |p| {
207	                // ragged skirt: radial wobble strongest at the base ring
208	                let w = (1.0 - (p.y + h * 0.5) / h).clamp(0.0, 1.0);
209	                let a = p.z.atan2(p.x);
210	                let f = 1.0 + 0.22 * w * ((a * 5.0 + seed).sin() * 0.6 + (a * 11.0 + seed * 2.3).sin() * 0.4);
211	                Vec3::new(p.x * f, p.y - 0.12 * w * (a * 7.0 + seed).sin().abs(), p.z * f)
212	            },
213	            move |p, _| mixc(mulc(dark, tier_tone), mulc(light, tier_tone), (p.y + h * 0.5) / h * 0.9 + 0.1),
214	        );
215	    }
216	    acc.plain(&cone(0.16, 1.1, 6), Transform::from_xyz(0.0, 1.7 + 4.0 * 1.12 + 2.0, 0.0), dark);
217	    acc.build()
218	}
219	
220	/// Faceted noise-deformed boulder; upward faces turn to moss.
221	fn rock_mesh(seed: u32) -> Mesh {
222	    let mut m: Mesh = Sphere::new(1.0).mesh().ico(2).expect("ico");
223	    m.duplicate_vertices();
224	    let perlin = noise::Perlin::new(seed);
225	    let s = seed as f64 * 3.7;
226	    if let Some(VertexAttributeValues::Float32x3(pos)) = m.attribute_mut(Mesh::ATTRIBUTE_POSITION) {
227	        for p in pos.iter_mut() {
228	            let d = Vec3::from(*p).normalize();
229	            let q = [d.x as f64 * 1.4 + s, d.y as f64 * 1.4, d.z as f64 * 1.4];
230	            let q2 = [d.x as f64 * 3.7 + s, d.y as f64 * 3.7, d.z as f64 * 3.7];
231	            let r = 1.0 + 0.30 * perlin.get(q) as f32 + 0.09 * perlin.get(q2) as f32;
232	            let v = d * r * Vec3::new(1.2, 0.85, 1.0);
233	            *p = [v.x, v.y.max(-0.55), v.z];
234	        }
235	    }
236	    m.compute_flat_normals();
237	    let nrm: Vec<[f32; 3]> = m.attribute(Mesh::ATTRIBUTE_NORMAL).and_then(|a| a.as_float3()).unwrap().to_vec();
238	    let pos: Vec<[f32; 3]> = m.attribute(Mesh::ATTRIBUTE_POSITION).and_then(|a| a.as_float3()).unwrap().to_vec();
239	    let mut col = Vec::with_capacity(pos.len());
240	    for (k, n) in nrm.iter().enumerate() {
241	        let p = pos[k];
242	        let n_i = perlin.get([p[0] as f64 * 2.3 + s, p[1] as f64 * 2.3, p[2] as f64 * 2.3]) as f32;
243	        let moss = ((n[1] + 0.25 * n_i - 0.38) / 0.35).clamp(0.0, 1.0);
244	        let tone = 0.75 + 0.35 * (0.5 + 0.5 * n_i);
245	        let stone = rgb(0.14 * tone, 0.14 * tone, 0.15 * tone);
246	        let green = rgb(0.02 + 0.012 * n_i.abs(), 0.065 + 0.03 * n_i.abs(), 0.022);
247	        col.push(mixc(stone, green, moss));
248	    }
249	    m.insert_attribute(Mesh::ATTRIBUTE_COLOR, col);
250	    m
251	}
