353	/// Discover `assets/models/*.glb` / `.gltf` and request the first scene of each through the AssetServer.
354	fn load_models(server: Res<AssetServer>, mut lib: ResMut<ModelLibrary>) {
355	    let Ok(rd) = std::fs::read_dir(assets_dir().join("models")) else { return };
356	    let mut files: Vec<String> = rd
357	        .flatten()
358	        .filter_map(|e| e.file_name().into_string().ok())
359	        .filter(|n| matches!(n.rsplit('.').next().map(str::to_ascii_lowercase).as_deref(), Some("glb" | "gltf")))
360	        .collect();
361	    files.sort();
362	    for f in files {
363	        let handle = server.load(GltfAssetLabel::Scene(0).from_asset(format!("models/{f}")));
364	        lib.models.push((f.rsplit_once('.').map_or(f.clone(), |(s, _)| s.to_string()), handle));
365	    }
366	}
