383	#[allow(clippy::too_many_arguments)]
384	fn sync_props(
385	    mut commands: Commands,
386	    version: Res<TerrainVersion>,
387	    mut seen: Local<Option<u32>>,
388	    spec: Res<WorldSpec>,
389	    grid: Res<TerrainGrid>,
390	    assets: Option<Res<PropAssets>>,
391	    lib: Res<ModelLibrary>,
392	    old: Query<Entity, With<PropRoot>>,
393	    mut meshes: ResMut<Assets<Mesh>>,
394	    mut mats: ResMut<Assets<StandardMaterial>>,
395	) {
396	    let Some(assets) = assets else { return };
397	    if *seen == Some(version.0) {
398	        return;
399	    }
400	    *seen = Some(version.0);
401	    for e in &old {
402	        commands.entity(e).despawn();
403	    }
404	    let mut cx = Ctx { grid: &grid.0, spec: &spec, next_id: 0 };
405	    for (n, it) in generate_scatter_plan(&spec, &grid.0).iter().enumerate() {
406	        let tf = Transform { translation: it.pos, rotation: it.rot, scale: Vec3::splat(it.scale) };
407	        let n = n as u32;
408	        match it.kind {
409	            ScatterKind::Pine => {
410	                let o = cx.obj("PineTree", ObjectCategory::Vegetation, Vec3::new(2.0, 4.2, 2.0) * it.scale);
411	                let h = assets.pines[(hash01(n) * assets.pines.len() as f32) as usize % assets.pines.len()].clone();
412	                commands.spawn((Name::new("PineTree"), o, Mesh3d(h), MeshMaterial3d(assets.mats.veg.clone()), tf));
413	            }
414	            ScatterKind::Boulder => {
415	                let o = cx.obj("Boulder", ObjectCategory::Rock, Vec3::new(1.2, 0.8, 1.0) * it.scale);
416	                let h = assets.rocks[(hash01(n + 7) * assets.rocks.len() as f32) as usize % assets.rocks.len()].clone();
417	                commands.spawn((Name::new("Boulder"), o, Mesh3d(h), MeshMaterial3d(assets.mats.rock.clone()), tf));
418	            }
419	            ScatterKind::Grass => {
420	                let o = cx.obj("GrassClump", ObjectCategory::Vegetation, Vec3::new(0.3, 0.35, 0.3) * it.scale);
421	                let h = assets.grass[n as usize % assets.grass.len()].clone();
422	                commands.spawn((Name::new("GrassClump"), o, Mesh3d(h), MeshMaterial3d(assets.mats.blade.clone()), tf, NotShadowCaster));
423	            }
424	            ScatterKind::Reed => {
425	                let o = cx.obj("Reeds", ObjectCategory::Vegetation, Vec3::new(0.35, 1.0, 0.35) * it.scale);
426	                let h = assets.reeds[n as usize % assets.reeds.len()].clone();
427	                commands.spawn((Name::new("Reeds"), o, Mesh3d(h), MeshMaterial3d(assets.mats.blade.clone()), tf, NotShadowCaster));
428	            }
429	            ScatterKind::WoodenPier => spawn_pier(&mut commands, &mut cx, &assets, &mut meshes, it),
430	            ScatterKind::CampfireSite => spawn_camp(&mut commands, &mut cx, &assets, &mut meshes, &mut mats, it),
431	        }
432	    }
433	    // external models: ring around the camp, ground-snapped
434	    let camp = Vec2::from(spec.camp_center);
435	    for (i, (name, scene)) in lib.models.iter().enumerate() {
436	        let a = 0.6 + i as f32 * 0.9;
437	        let p = camp + Vec2::new(a.cos(), a.sin()) * 9.0;
438	        let o = cx.obj(name, ObjectCategory::Model, Vec3::splat(1.0));
439	        commands.spawn((Name::new(name.clone()), o, WorldAssetRoot(scene.clone()), Transform::from_xyz(p.x, grid.0.sample_height(p.x, p.y), p.y)));
440	    }
441	}
