447	fn spawn_pier(commands: &mut Commands, cx: &mut Ctx, assets: &PropAssets, meshes: &mut Assets<Mesh>, it: &ScatterItem) {
448	    let len = it.scale;
449	    let root = it.pos;
450	    let rot = it.rot;
451	    let ground_rel = |x: f32, z: f32| {
452	        let w = root + rot * Vec3::new(x, 0.0, z);
453	        cx.grid.sample_height(w.x, w.z) - root.y
454	    };
455	    let mut wood = MeshAcc::default();
456	    let plank_m = cube(0.46, 0.09, 2.1);
457	    let mut x = 0.0;
458	    let mut k = 0;
459	    while x + 0.46 <= len {
460	        let tone = 0.75 + 0.5 * hash01(k + 900);
461	        let c = rgb(0.17 * tone, 0.105 * tone, 0.055 * tone);
462	        wood.plain(&plank_m, Transform::from_xyz(x + 0.25, 0.0, 0.0).with_rotation(Quat::from_rotation_y((hash01(k + 5) - 0.5) * 0.02)), c);
463	        x += 0.5;
464	        k += 1;
465	    }
466	    let beam = rgb(0.10, 0.06, 0.035);
467	    for z in [-0.8, 0.8] {
468	        wood.plain(&cube(len, 0.14, 0.16), Transform::from_xyz(len * 0.5, -0.14, z), beam);
469	    }
470	    let mut px = 0.6;
471	    let mut pk = 0;
472	    while px < len {
473	        for z in [-0.95, 0.95] {
474	            let g = ground_rel(px, z) - 0.5;
475	            let top = 0.6;
476	            let h = top - g;
477	            let tall = if px + 2.4 >= len { 0.0 } else { 0.0 };
478	            let _ = tall;
479	            wood.push(
480	                &cyl(0.12, h, 8),
481	                Transform::from_xyz(px, g + h * 0.5, z),
482	                |p| p,
483	                move |p, _| {
484	                    let y = p.y + h * 0.5 + g; // relative to deck
485	                    if y < -0.7 { mixc(rgb(0.04, 0.07, 0.035), rgb(0.07, 0.045, 0.03), (y + 1.5).clamp(0.0, 1.0)) } else { rgb(0.085, 0.052, 0.03) }
486	                },
487	            );
488	        }
489	        px += 2.4;
490	        pk += 1;
491	    }
492	    let _ = pk;
493	    for z in [-0.95, 0.95] {
494	        let start = 1.6;
495	        wood.plain(&cube(len - start, 0.07, 0.07), Transform::from_xyz(start + (len - start) * 0.5, 0.52, z), rgb(0.12, 0.07, 0.04));
496	    }
497	    // lantern post at the far end
498	    let (lx, lz) = (len - 0.35, -0.95);
499	    wood.plain(&cyl(0.05, 2.4, 6), Transform::from_xyz(lx, 1.2, lz), rgb(0.07, 0.045, 0.03));
500	    wood.plain(&cube(0.05, 0.05, 0.7), Transform::from_xyz(lx, 2.38, lz + 0.35), rgb(0.07, 0.045, 0.03));
501	    let lant_pos = Vec3::new(lx, 2.12, lz + 0.62);
502	    wood.plain(&cube(0.012, 0.2, 0.012), Transform::from_xyz(lant_pos.x, lant_pos.y + 0.2, lant_pos.z), rgb(0.03, 0.03, 0.03));
503	
504	    // boat: hull, rim, seat, oars
505	    let mut boat = MeshAcc::default();
506	    let hull = rgb(0.075, 0.05, 0.03);
507	    let paint = rgb(0.08, 0.05, 0.11);
508	    boat.plain(&cube(2.7, 0.08, 0.95), Transform::from_xyz(0.0, 0.0, 0.0), hull);
509	    for s in [-1.0, 1.0] {
510	        boat.plain(&cube(2.7, 0.36, 0.07), Transform::from_xyz(0.0, 0.2, s * 0.46).with_rotation(Quat::from_rotation_x(-s * 0.12)), paint);
511	        boat.plain(&cube(0.95, 0.36, 0.07), Transform::from_xyz(1.55, 0.2, s * 0.26).with_rotation(Quat::from_rotation_y(s * 0.52)), paint);
512	    }
513	    boat.plain(&cube(0.07, 0.36, 0.95), Transform::from_xyz(-1.35, 0.2, 0.0), paint);
514	    boat.plain(&cube(0.35, 0.06, 0.92), Transform::from_xyz(0.1, 0.3, 0.0), hull);
515	    boat.plain(&cyl(0.025, 1.9, 5), Transform::from_xyz(-0.4, 0.38, 0.0).with_rotation(Quat::from_rotation_x(FRAC_PI_2) * Quat::from_rotation_z(0.25)), rgb(0.14, 0.09, 0.05));
516	
517	    let half = Vec3::new(len * 0.5, 1.4, 1.4);
518	    let o = cx.obj("WoodenPier", ObjectCategory::Structure, half);
519	    let boat_x = (len * 0.55).max(2.0);
520	    let lantern_light = (
521	        NightLight { base: 26_000.0 },
522	        PointLight { color: Color::srgb(1.0, 0.68, 0.32), intensity: 0.0, range: 24.0, radius: 0.08, shadow_maps_enabled: false, ..default() },
523	        Transform::from_translation(lant_pos),
524	    );
525	    commands
526	        .spawn((Name::new("WoodenPier"), o, mul_tf(root, rot), Visibility::default()))
527	        .with_children(|c| {
528	            c.spawn((Name::new("PierDeck"), Mesh3d(meshes.add(wood.build())), MeshMaterial3d(assets.mats.wood.clone()), Transform::default()));
529	            c.spawn((
530	                Name::new("RowBoat"),
531	                Mesh3d(meshes.add(boat.build())),
532	                MeshMaterial3d(assets.mats.wood.clone()),
533	                Transform::from_xyz(boat_x, -0.52, 2.4).with_rotation(Quat::from_rotation_y(0.18)),
534	                Bob { phase: hash01(77) * TAU, base_y: -0.52, yaw: 0.18 },
535	            ));
536	            c.spawn((Name::new("PierLanternGlass"), Mesh3d(meshes.add(cube(0.18, 0.26, 0.18))), MeshMaterial3d(assets.mats.lantern_glass.clone()), Transform::from_translation(lant_pos), NotShadowCaster));
537	            c.spawn(lantern_light);
538	        });
539	}
