541	fn spawn_camp(commands: &mut Commands, cx: &mut Ctx, assets: &PropAssets, meshes: &mut Assets<Mesh>, _mats: &mut Assets<StandardMaterial>, it: &ScatterItem) {
542	    let root = it.pos;
543	    let g = |x: f32, z: f32| cx.grid.sample_height(root.x + x, root.z + z) - root.y;
544	    let mut acc = MeshAcc::default();
545	    let rock_m = &assets.rocks[0];
546	    let _ = rock_m;
547	    let stone_mesh = rock_mesh(5);
548	    // stone ring
549	    for k in 0..11u32 {
550	        let a = k as f32 / 11.0 * TAU;
551	        let (x, z) = (a.cos() * 0.95, a.sin() * 0.95);
552	        let s = 0.26 + 0.1 * hash01(k + 300);
553	        acc.push(&stone_mesh, Transform::from_xyz(x, g(x, z) + 0.08, z).with_rotation(Quat::from_rotation_y(hash01(k + 310) * TAU)).with_scale(Vec3::new(s * 1.2, s * 0.8, s)), |p| p, |_, c| c);
554	    }
555	    // charred logs piled like a teepee
556	    for k in 0..6u32 {
557	        let a = k as f32 / 6.0 * TAU + 0.3;
558	        let radial = Vec3::new(a.cos(), 0.0, a.sin());
559	        let rot = Quat::from_rotation_y(-a) * Quat::from_rotation_z(1.0);
560	        acc.push(&cyl(0.075, 1.15, 7), Transform::from_translation(radial * 0.32 + Vec3::Y * 0.3).with_rotation(rot), |p| p, |p, _| mixc(rgb(0.07, 0.04, 0.025), rgb(0.012, 0.01, 0.01), (p.y + 0.57) * 1.0));
561	    }
562	    // log benches
563	    for (k, a) in [0.5_f32, 2.35, 4.05].into_iter().enumerate() {
564	        let (x, z) = (a.cos() * 2.9, a.sin() * 2.9);
565	        let rot = Quat::from_rotation_y(-(a + FRAC_PI_2)) * Quat::from_rotation_z(FRAC_PI_2);
566	        let bark = rgb(0.055 + 0.01 * k as f32, 0.04, 0.026);
567	        acc.push(&cyl(0.22, 2.1, 9), Transform::from_xyz(x, g(x, z) + 0.2, z).with_rotation(rot), |p| p, move |p, _| mulc(bark, 0.8 + 0.6 * (p.x / 0.22).abs() * 0.0 + 0.2 * (p.y * 7.0).sin().abs()));
568	    }
569	    // firewood stack by the tent
570	    for (k, (dx, dy)) in [(-0.2, 0.0), (0.0, 0.0), (0.2, 0.0), (-0.1, 0.17), (0.1, 0.17), (0.0, 0.34)].into_iter().enumerate() {
571	        let (x, z) = (-2.6 + dx, 4.8);
572	        acc.plain(&cyl(0.09, 1.0, 7), Transform::from_xyz(x, g(x, z) + 0.1 + dy, z).with_rotation(Quat::from_rotation_x(FRAC_PI_2)), rgb(0.14 - 0.01 * k as f32, 0.08, 0.04));
573	    }
574	    // backpack & crate
575	    let (bx, bz) = (-2.4, 2.2);
576	    acc.plain(&cube(0.5, 0.65, 0.34), Transform::from_xyz(bx, g(bx, bz) + 0.33, bz).with_rotation(Quat::from_rotation_y(0.7)), rgb(0.03, 0.07, 0.04));
577	    acc.plain(&cube(0.38, 0.22, 0.36), Transform::from_xyz(bx - 0.4, g(bx, bz) + 0.11, bz + 0.5).with_rotation(Quat::from_rotation_y(0.3)), rgb(0.12, 0.075, 0.04));
578	
579	    let tent_off = Vec2::new(-4.8, 3.2);
580	    let flames = [(0.36_f32, 1.05_f32, 0usize, Vec3::ZERO), (0.26, 0.8, 1, Vec3::ZERO), (0.15, 0.5, 2, Vec3::ZERO), (0.14, 0.55, 0, Vec3::new(0.2, 0.0, 0.1)), (0.12, 0.5, 1, Vec3::new(-0.18, 0.0, 0.12)), (0.12, 0.45, 0, Vec3::new(0.05, 0.0, -0.2))];
581	
582	    let o = cx.obj("CampfireSite", ObjectCategory::Camp, Vec3::new(5.5, 1.6, 5.5));
583	    let tent_y = g(tent_off.x, tent_off.y);
584	    let static_mesh = meshes.add(acc.build());
585	    commands
586	        .spawn((Name::new("CampfireSite"), o, mul_tf(root, it.rot), Visibility::default()))
587	        .with_children(|c| {
588	            c.spawn((Name::new("CampProps"), Mesh3d(static_mesh), MeshMaterial3d(assets.mats.rock.clone()), Transform::default()));
589	            c.spawn((Name::new("Tent"), Mesh3d(assets.tent.clone()), MeshMaterial3d(assets.mats.canvas.clone()), Transform::from_xyz(tent_off.x, tent_y, tent_off.y).with_rotation(Quat::from_rotation_y(0.9))));
590	            c.spawn((Name::new("EmberBed"), Mesh3d(meshes.add(Sphere::new(0.5).mesh().ico(2).expect("ico"))), MeshMaterial3d(assets.mats.ember.clone()), Transform::from_xyz(0.0, 0.08, 0.0).with_scale(Vec3::new(1.0, 0.28, 1.0)), NotShadowCaster));
591	            for (k, (r, h, layer, off)) in flames.iter().enumerate() {
592	                let base = Vec3::new(*r, *h, *r);
593	                c.spawn((
594	                    Name::new("Flame"),
595	                    Flame { phase: k as f32 * 1.7, base },
596	                    Mesh3d(assets.flame_cone.clone()),
597	                    MeshMaterial3d(assets.mats.flame[*layer].clone()),
598	                    Transform::from_translation(Vec3::new(0.0, 0.25 + h * 0.5, 0.0) + *off).with_scale(base),
599	                    NotShadowCaster,
600	                ));
601	            }
602	            for k in 0..26u32 {
603	                let life = 1.1 + 1.8 * hash01(k + 500);
604	                c.spawn((
605	                    Name::new("Spark"),
606	                    Spark { age: hash01(k + 520) * life, life, vel: Vec3::new((hash01(k + 540) - 0.5) * 0.6, 1.2 + 1.6 * hash01(k + 560), (hash01(k + 580) - 0.5) * 0.6), origin: Vec3::new((hash01(k + 600) - 0.5) * 0.4, 0.5, (hash01(k + 620) - 0.5) * 0.4), seed: hash01(k + 640) * TAU },
607	                    Mesh3d(assets.spark_mesh.clone()),
608	                    MeshMaterial3d(assets.mats.spark.clone()),
609	                    Transform::default(),
610	                    NotShadowCaster,
611	                ));
612	            }
613	            c.spawn((
614	                Name::new("CampfireLight"),
615	                NightLight { base: 70_000.0 },
616	                PointLight { color: Color::srgb(1.0, 0.52, 0.2), intensity: 0.0, range: 45.0, radius: 0.35, shadow_maps_enabled: cx.spec.shadows, ..default() },
617	                VolumetricLight,
618	                Transform::from_xyz(0.0, 0.95, 0.0),
619	            ));
620	        });
621	}
622	
623	// ───────────────────────────── Animation ─────────────────────────────
624	
625	fn animate_flames(time: Res<Time>, mut q: Query<(&Flame, &mut Transform)>) {
626	    let t = time.elapsed_secs();
627	    for (f, mut tf) in &mut q {
628	        let p = f.phase;
629	        let flick = 1.0 + 0.22 * (t * 11.0 + p).sin() * (t * 4.3 + p * 2.0).cos() + 0.10 * (t * 27.0 + p).sin();
630	        tf.scale = Vec3::new(f.base.x * (1.0 + 0.12 * (t * 8.0 + p).cos()), f.base.y * flick, f.base.z * (1.0 + 0.12 * (t * 9.0 + p).sin()));
631	        tf.translation.y = 0.25 + tf.scale.y * 0.5;
632	        tf.rotation = Quat::from_rotation_z(0.10 * (t * 3.1 + p).sin()) * Quat::from_rotation_x(0.10 * (t * 2.6 + p * 1.3).cos());
633	    }
634	}
635	
636	fn animate_sparks(time: Res<Time>, mut q: Query<(&mut Spark, &mut Transform)>) {
637	    let dt = time.delta_secs();
638	    for (mut s, mut tf) in &mut q {
639	        s.age += dt;
640	        if s.age >= s.life {
641	            s.age = 0.0;
642	            s.seed = rand::random::<f32>() * TAU;
643	            s.vel = Vec3::new((rand::random::<f32>() - 0.5) * 0.7, 1.2 + 1.8 * rand::random::<f32>(), (rand::random::<f32>() - 0.5) * 0.7);
644	        }
645	        let t = s.age;
646	        let sway = Vec3::new((t * 4.0 + s.seed).sin(), 0.0, (t * 3.3 + s.seed).cos()) * 0.12 * t;
647	        tf.translation = s.origin + s.vel * t - Vec3::Y * 0.15 * t * t + sway;
648	        let k = 1.0 - (t / s.life).powi(2);
649	        tf.scale = Vec3::splat(k.max(0.001));
650	    }
651	}
652	
653	fn animate_bobbing(time: Res<Time>, mut q: Query<(&Bob, &mut Transform)>) {
654	    let t = time.elapsed_secs();
655	    for (b, mut tf) in &mut q {
656	        tf.translation.y = b.base_y + 0.025 * (t * 1.3 + b.phase).sin();
657	        tf.rotation = Quat::from_rotation_y(b.yaw) * Quat::from_rotation_z(0.025 * (t * 1.1 + b.phase).sin()) * Quat::from_rotation_x(0.02 * (t * 0.9 + b.phase).cos());
658	    }
659	}
