69	pub fn build_terrain_mesh(g: &HeightfieldGrid, splats: &[Splat]) -> Mesh {
70	    let n = g.n;
71	    let mut pos = Vec::with_capacity(n * n);
72	    let mut nrm = Vec::with_capacity(n * n);
73	    let mut col = Vec::with_capacity(n * n);
74	    let mut uv = Vec::with_capacity(n * n);
75	    for j in 0..n {
76	        for i in 0..n {
77	            let (x, z) = g.grid_to_world(i, j);
78	            pos.push([x, g.heights[g.idx(i, j)], z]);
79	            nrm.push(g.sample_normal(x, z).to_array());
80	            let s = &splats[g.idx(i, j)];
81	            // two-octave tint variation so large splat areas do not look flat
82	            let t = 0.82 + 0.36 * (0.65 * colour_jitter(x * 0.35, z * 0.35) + 0.35 * colour_jitter(x * 1.9, z * 1.9));
83	            col.push([(s.albedo[0] * t).min(1.0), (s.albedo[1] * t).min(1.0), (s.albedo[2] * t).min(1.0), 1.0]);
84	            uv.push([i as f32 / (n - 1) as f32, j as f32 / (n - 1) as f32]);
85	        }
86	    }
87	    let mut idx = Vec::with_capacity((n - 1) * (n - 1) * 6);
88	    for j in 0..n - 1 {
89	        for i in 0..n - 1 {
90	            let (a, b, c, d) = ((j * n + i) as u32, (j * n + i + 1) as u32, ((j + 1) * n + i) as u32, ((j + 1) * n + i + 1) as u32);
91	            idx.extend_from_slice(&[a, c, b, b, c, d]);
92	        }
93	    }
94	    Mesh::new(PrimitiveTopology::TriangleList, RenderAssetUsages::default())
95	        .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, pos)
96	        .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, nrm)
97	        .with_inserted_attribute(Mesh::ATTRIBUTE_UV_0, uv)
98	        .with_inserted_attribute(Mesh::ATTRIBUTE_COLOR, col)
99	        .with_inserted_indices(Indices::U32(idx))
100	}
101	
102	fn setup_terrain(mut commands: Commands, spec: Res<WorldSpec>, mut meshes: ResMut<Assets<Mesh>>, mut mats: ResMut<Assets<StandardMaterial>>) {
103	    let grid = generate_world(&spec);
104	    let splats = grid.build_splatmap(&spec);
105	    commands.spawn((
106	        Name::new("Terrain"),
107	        TerrainMesh,
108	        Mesh3d(meshes.add(build_terrain_mesh(&grid, &splats))),
109	        MeshMaterial3d(mats.add(StandardMaterial { base_color: Color::WHITE, perceptual_roughness: 0.88, reflectance: 0.2, ..default() })),
110	    ));
111	    commands.insert_resource(TerrainGrid(grid));
112	    commands.insert_resource(GeoKey::of(&spec));
113	}
114	
115	/// Geometry-relevant spec change → regenerate heightfield + mesh; props/water follow via `TerrainVersion`.
116	fn rebuild_on_spec_change(
117	    spec: Res<WorldSpec>,
118	    mut key: ResMut<GeoKey>,
119	    mut grid: ResMut<TerrainGrid>,
120	    mut version: ResMut<TerrainVersion>,
121	    terrain: Query<&Mesh3d, With<TerrainMesh>>,
122	    mut meshes: ResMut<Assets<Mesh>>,
123	) {
124	    if !spec.is_changed() {
125	        return;
126	    }
127	    let new = GeoKey::of(&spec);
128	    if new == *key {
129	        return;
130	    }
131	    let terrain_changed = new.terrain != key.terrain || new.lake != key.lake;
132	    *key = new;
133	    if terrain_changed {
134	        grid.0 = generate_world(&spec);
135	        if let Ok(h) = terrain.single() {
136	            let splats = grid.0.build_splatmap(&spec);
137	            let _ = meshes.insert(&h.0, build_terrain_mesh(&grid.0, &splats));
138	        }
139	    }
140	    version.0 += 1;
141	}
