1	//! Editor camera (doc 01): orbit, depth pan, exponential zoom, fly mode, focus.
2	
3	use bevy::input::mouse::{AccumulatedMouseMotion, AccumulatedMouseScroll, MouseScrollUnit};
4	use bevy::prelude::*;
5	use bevy::window::PrimaryWindow;
6	use bevy_egui::EguiContexts;
7	
8	use crate::scene::TerrainGrid;
9	
10	const K_ROT: f32 = 0.0052;
11	const ZOOM_RATE: f32 = 0.15;
12	const PITCH_LIM: f32 = 89.0 * std::f32::consts::PI / 180.0;
13	
14	#[derive(Clone, Copy, PartialEq, Eq, Debug, Reflect)]
15	pub enum CamMode {
16	    Orbit,
17	    Pan,
18	    Fly,
19	}
20	
21	#[derive(Component, Reflect)]
22	#[reflect(Component)]
23	pub struct EditorCamera {
24	    pub yaw: f32,
25	    pub pitch: f32,
26	    pub pivot: Vec3,
27	    pub distance: f32,
28	    /// Base fly speed v0 (m/s).
29	    pub fly_speed: f32,
30	    /// Shift ramp: a = accel + 1.
31	    pub fly_accel: f32,
32	    pub v_target: f32,
33	    pub vel: Vec3,
34	    pub mode: Option<CamMode>,
35	    pub focus: Option<(Vec3, f32)>,
36	}
37	
38	impl Default for EditorCamera {
39	    fn default() -> Self {
40	        Self { yaw: 0.0, pitch: 0.3, pivot: Vec3::ZERO, distance: 30.0, fly_speed: 9.0, fly_accel: 1.5, v_target: 9.0, vel: Vec3::ZERO, mode: None, focus: None }
41	    }
42	}
43	
44	impl EditorCamera {
45	    pub fn forward(&self) -> Vec3 {
46	        let (cp, sp) = (self.pitch.cos(), self.pitch.sin());
47	        Vec3::new(cp * self.yaw.sin(), -sp, cp * self.yaw.cos())
48	    }
49	    pub fn eye(&self) -> Vec3 {
50	        self.pivot - self.forward() * self.distance
51	    }
52	    /// Focus on a bounding sphere: distance = max(radius / sin(fov/2), 2).
53	    pub fn focus_on(&mut self, center: Vec3, radius: f32, fov_y: f32) {
54	        self.focus = Some((center, (radius / (fov_y * 0.5).sin()).max(2.0)));
55	    }
56	}
57	
58	pub struct EditorCameraPlugin;
59	
60	impl Plugin for EditorCameraPlugin {
61	    fn build(&self, app: &mut App) {
62	        app.add_systems(Update, editor_camera_system);
63	    }
64	}
65	
66	#[allow(clippy::too_many_arguments)]
67	fn editor_camera_system(
68	    time: Res<Time>,
69	    mouse: Res<ButtonInput<MouseButton>>,
70	    keys: Res<ButtonInput<KeyCode>>,
71	    motion: Res<AccumulatedMouseMotion>,
72	    scroll: Res<AccumulatedMouseScroll>,
73	    terrain: Option<Res<TerrainGrid>>,
74	    mut egui: EguiContexts,
75	    window: Single<&Window, With<PrimaryWindow>>,
76	    mut cam: Single<(&mut EditorCamera, &mut Transform, &Camera, &Projection, &GlobalTransform)>,
77	) {
78	    let (ctrl, tf, camera, proj, gtf) = &mut *cam;
79	    let dt = time.delta_secs().min(0.1);
80	    let fov_y = if let Projection::Perspective(p) = proj { p.fov } else { 1.0 };
81	    let blocked = egui.ctx_mut().map(|c| c.egui_wants_pointer_input() || c.is_pointer_over_egui()).unwrap_or(false);
82	    let alt = keys.any_pressed([KeyCode::AltLeft, KeyCode::AltRight]);
83	    let shift = keys.any_pressed([KeyCode::ShiftLeft, KeyCode::ShiftRight]);
84	    let d = motion.delta;
85	
86	    // mode selection: only starts when the pointer is not over egui; ends on release
87	    if !blocked {
88	        if mouse.just_pressed(MouseButton::Right) {
89	            ctrl.mode = Some(CamMode::Fly);
90	            ctrl.v_target = ctrl.fly_speed;
91	            ctrl.vel = Vec3::ZERO;
92	        } else if mouse.just_pressed(MouseButton::Middle) {
93	            ctrl.mode = Some(if shift { CamMode::Pan } else { CamMode::Orbit });
94	        } else if mouse.just_pressed(MouseButton::Left) && alt {
95	            ctrl.mode = Some(if shift { CamMode::Pan } else { CamMode::Orbit });
96	        }
97	    }
98	    let held = match ctrl.mode {
99	        Some(CamMode::Fly) => mouse.pressed(MouseButton::Right),
100	        Some(_) => mouse.pressed(MouseButton::Middle) || mouse.pressed(MouseButton::Left),
101	        None => false,
102	    };
103	    if !held {
104	        if ctrl.mode == Some(CamMode::Fly) {
105	            ctrl.pivot = ctrl.eye() + ctrl.forward() * ctrl.distance; // pivot carried along with the eye
106	        }
107	        ctrl.mode = None;
108	        ctrl.vel = Vec3::ZERO;
109	    }
110	
111	    let fwd = ctrl.forward();
112	    let right = fwd.cross(Vec3::Y).normalize_or_zero();
113	    let up = right.cross(fwd);
114	
115	    match ctrl.mode {
116	        Some(CamMode::Orbit) => {
117	            ctrl.yaw -= d.x * K_ROT;
118	            ctrl.pitch = (ctrl.pitch - d.y * K_ROT).clamp(-PITCH_LIM, PITCH_LIM);
119	        }
120	        Some(CamMode::Pan) => {
121	            let u = 2.0 * ctrl.distance * (fov_y * 0.5).tan() / window.height();
122	            ctrl.pivot += (-right * d.x + up * d.y) * u;
123	        }
124	        Some(CamMode::Fly) => {
125	            let eye = ctrl.eye();
126	            ctrl.yaw -= d.x * K_ROT;
127	            ctrl.pitch = (ctrl.pitch + d.y * K_ROT).clamp(-PITCH_LIM, PITCH_LIM); // FPS look: mouse up = look up
128	            let (fwd, right) = (ctrl.forward(), ctrl.forward().cross(Vec3::Y).normalize_or_zero());
129	            let ax = |p: KeyCode, n: KeyCode| keys.pressed(p) as i32 as f32 - keys.pressed(n) as i32 as f32;
130	            let wish = (fwd * ax(KeyCode::KeyW, KeyCode::KeyS) + right * ax(KeyCode::KeyD, KeyCode::KeyA) + Vec3::Y * ax(KeyCode::KeyE, KeyCode::KeyQ)).normalize_or_zero();
131	            if scroll.delta.y != 0.0 {
132	                ctrl.fly_speed = (ctrl.fly_speed * (scroll.delta.y * 0.1).exp()).clamp(0.1, 500.0);
133	            }
134	            ctrl.v_target = if shift { (ctrl.v_target * (ctrl.fly_accel + 1.0).powf(dt)).min(500.0) } else { ctrl.fly_speed };
135	            let target = wish * ctrl.v_target;
136	            ctrl.vel = ctrl.vel.lerp(target, 1.0 - (-dt / 0.08).exp());
137	            let new_eye = eye + ctrl.vel * dt;
138	            ctrl.pivot = new_eye + ctrl.forward() * ctrl.distance;
139	        }
140	        None => {}
141	    }
142	
143	    // zoom (wheel), cursor-directed when the cursor ray hits the terrain
144	    if ctrl.mode != Some(CamMode::Fly) && !blocked && scroll.delta.y != 0.0 {
145	        let notches = match scroll.unit {
146	            MouseScrollUnit::Line => scroll.delta.y,
147	            MouseScrollUnit::Pixel => scroll.delta.y / 40.0,
148	        } * if shift { 3.0 } else { 1.0 };
149	        let hit = window
150	            .cursor_position()
151	            .and_then(|c| camera.viewport_to_world(*gtf, c).ok())
152	            .and_then(|ray| terrain.as_ref().and_then(|t| t.0.raycast(ray.origin, *ray.direction)));
153	        let eye = ctrl.eye();
154	        match hit {
155	            Some(p) => {
156	                let eye2 = eye + (p - eye) * (1.0 - (-notches * ZOOM_RATE).exp());
157	                ctrl.distance = (p - eye2).length().clamp(0.1, 5000.0);
158	                ctrl.pivot = eye2 + ctrl.forward() * ctrl.distance;
159	            }
160	            None => ctrl.distance = (ctrl.distance * (-notches * ZOOM_RATE).exp()).clamp(0.1, 5000.0),
161	        }
162	    }
163	
164	    // focus (F): selection AABB is not available yet, so focus the point under the cursor (or current pivot)
165	    if keys.just_pressed(KeyCode::KeyF) && !blocked {
166	        let hit = window
167	            .cursor_position()
168	            .and_then(|c| camera.viewport_to_world(*gtf, c).ok())
169	            .and_then(|ray| terrain.as_ref().and_then(|t| t.0.raycast(ray.origin, *ray.direction)));
170	        let c = hit.unwrap_or(ctrl.pivot);
171	        ctrl.focus_on(c, 4.0, fov_y);
172	    }
173	    if let Some((tp, td)) = ctrl.focus {
174	        let s = 1.0 - (-dt / 0.12).exp();
175	        ctrl.pivot = ctrl.pivot.lerp(tp, s);
176	        ctrl.distance += (td - ctrl.distance) * s;
177	        if ctrl.pivot.distance(tp) < 1e-3 && (ctrl.distance - td).abs() < 1e-3 {
178	            ctrl.focus = None;
179	        }
180	    }
181	
182	    **tf = Transform::from_translation(ctrl.eye()).looking_at(ctrl.pivot, Vec3::Y);
183	}
