86	
87	fn advance_clock(mut spec: ResMut<WorldSpec>, time: Res<Time>) {
88	    if spec.auto_sun {
89	        spec.time_of_day = (spec.time_of_day + time.delta_secs() * 0.15).rem_euclid(24.0);
90	    }
91	}
92	
93	#[allow(clippy::type_complexity)]
94	fn apply_time_of_day(
95	    spec: Res<WorldSpec>,
96	    mut sun: Query<(&mut Transform, &mut DirectionalLight), (With<Sun>, Without<Moon>)>,
97	    mut moon: Query<(&mut Transform, &mut DirectionalLight), (With<Moon>, Without<Sun>)>,
98	    mut cam: Query<(&mut Exposure, &mut DistanceFog)>,
99	    mut vol: Query<&mut FogVolume>,
100	    mut ambient: ResMut<GlobalAmbientLight>,
101	) {
102	    let t = spec.time_of_day;
103	    let dir = sun_direction(t);
104	    let d = daylight(t);
105	    let elev = dir.y;
106	    if let Ok((mut tf, mut l)) = sun.single_mut() {
107	        *tf = Transform::default().looking_to(-dir, Vec3::Y);
108	        l.illuminance = 130_000.0 * spec.sun_intensity * smoothstep(-0.04, 0.12, elev);
109	        l.shadow_maps_enabled = spec.shadows && elev > -0.03;
110	    }
111	    if let Ok((mut tf, mut l)) = moon.single_mut() {
112	        let mdir = Vec3::new(-dir.x, dir.y.abs().max(0.35), -dir.z).normalize();
113	        *tf = Transform::default().looking_to(-mdir, Vec3::Y);
114	        l.illuminance = 22.0 * (1.0 - d);
115	        l.shadow_maps_enabled = spec.shadows && d < 0.3;
116	    }
117	    for mut v in &mut vol {
118	        v.density_factor = if spec.fog_enabled { spec.fog_density * 1.6 } else { 0.0 };
119	    }
120	    let ev = EV_NIGHT + (EV_DAY - EV_NIGHT) * d.powf(0.8);
121	    ambient.brightness = 14.0 * (1.0 - d) + 450.0 * d;
122	    for (mut exp, mut fog) in &mut cam {
123	        exp.ev100 = ev;
124	        let vis = smoothstep(-0.25, 0.3, elev);
125	        let k = 0.015 + 0.985 * vis;
126	        let dusk = (1.0 - (elev.abs() * 4.0).min(1.0)) * vis; // warm tint near the horizon
127	        let c = Vec3::from(spec.fog_color) * k + Vec3::new(0.35, 0.12, -0.05) * dusk * 0.5;
128	        fog.color = Color::linear_rgb(c.x.max(0.0), c.y.max(0.0), c.z.max(0.0));
129	        fog.directional_light_color = Color::srgba(1.0, 0.75, 0.45, 0.4 * smoothstep(0.0, 0.2, elev));
130	        fog.falloff = FogFalloff::Exponential { density: if spec.fog_enabled { spec.fog_density } else { 0.0 } };
131	    }
132	}
133	
134	/// Feature toggles & quality preset → add/remove camera components.
135	fn apply_toggles(
136	    spec: Res<WorldSpec>,
137	    mut commands: Commands,
138	    cam: Query<Entity, With<Camera3d>>,
139	    sun: Query<Entity, With<Sun>>,
140	    mut shadow_map: ResMut<DirectionalLightShadowMap>,
141	) {
142	    if !spec.is_changed() {
143	        return;
144	    }
145	    shadow_map.size = match spec.quality_preset {
146	        QualityPreset::Low => 1024,
147	        QualityPreset::Medium => 2048,
148	        QualityPreset::High => 4096,
149	        QualityPreset::Ultra => 8192,
150	    };
151	    for e in &cam {
152	        let mut c = commands.entity(e);
153	        if spec.bloom { c.insert(Bloom::NATURAL); } else { c.remove::<Bloom>(); }
154	        if spec.reflections { c.insert(ScreenSpaceReflections::default()); } else { c.remove::<ScreenSpaceReflections>(); }
155	        if spec.god_rays { c.insert(VolumetricFog { ambient_intensity: 0.0, step_count: 48, ..default() }); } else { c.remove::<VolumetricFog>(); }
156	    }
157	    for e in &sun {
158	        if spec.god_rays { commands.entity(e).insert(VolumetricLight); } else { commands.entity(e).remove::<VolumetricLight>(); }
159	    }
160	}
161	
162	fn flicker_night_lights(spec: Res<WorldSpec>, time: Res<Time>, mut q: Query<(&NightLight, &mut PointLight)>) {
163	    let n = night_factor(spec.time_of_day);
164	    let t = time.elapsed_secs();
165	    let f = 1.0 + 0.10 * (t * 17.0).sin() * (t * 5.3).cos() + 0.05 * (t * 41.0).sin();
166	    for (nl, mut l) in &mut q {
167	        l.intensity = nl.base * n * f;
168	    }
169	}
170	
