172	mod tests {
173	    use super::*;
174	
175	    #[test]
176	    fn night_window_matches_spec() {
177	        assert_eq!(night_factor(12.0), 0.0);
178	        assert_eq!(night_factor(19.0), 0.0);
179	        assert_eq!(night_factor(20.0), 1.0);
180	        assert_eq!(night_factor(3.0), 1.0);
181	        assert_eq!(night_factor(7.0), 0.0);
182	        assert!(sun_direction(12.0).y > 0.99 && sun_direction(0.0).y < -0.99);
183	        assert!(daylight(12.0) > 0.99 && daylight(0.0) < 0.01);
184	    }
185	}
