143	/// Accumulates transformed, vertex-coloured primitives into one mesh.
144	#[derive(Default)]
145	struct MeshAcc {
146	    pos: Vec<[f32; 3]>,
147	    nrm: Vec<[f32; 3]>,
148	    col: Vec<[f32; 4]>,
149	    idx: Vec<u32>,
150	}
151	
152	impl MeshAcc {
153	    fn push(&mut self, mesh: &Mesh, tf: Transform, warp: impl Fn(Vec3) -> Vec3, color: impl Fn(Vec3, [f32; 4]) -> [f32; 4]) {
154	        let p = mesh.attribute(Mesh::ATTRIBUTE_POSITION).and_then(|a| a.as_float3()).expect("positions");
155	        let n = mesh.attribute(Mesh::ATTRIBUTE_NORMAL).and_then(|a| a.as_float3()).expect("normals");
156	        let c = match mesh.attribute(Mesh::ATTRIBUTE_COLOR) {
157	            Some(VertexAttributeValues::Float32x4(v)) => Some(v.as_slice()),
158	            _ => None,
159	        };
160	        let base = self.pos.len() as u32;
161	        for k in 0..p.len() {
162	            let lp = Vec3::from(p[k]);
163	            self.pos.push(tf.transform_point(warp(lp)).to_array());
164	            self.nrm.push((tf.rotation * (Vec3::from(n[k]) / tf.scale)).normalize_or_zero().to_array());
165	            self.col.push(color(lp, c.map_or([1.0; 4], |c| c[k])));
166	        }
167	        match mesh.indices() {
168	            Some(i) => self.idx.extend(i.iter().map(|i| base + i as u32)),
169	            None => self.idx.extend((0..p.len() as u32).map(|i| base + i)),
170	        }
171	    }
172	
173	    fn plain(&mut self, mesh: &Mesh, tf: Transform, col: [f32; 4]) {
174	        self.push(mesh, tf, |p| p, |_, _| col);
175	    }
176	
177	    fn build(self) -> Mesh {
178	        Mesh::new(PrimitiveTopology::TriangleList, RenderAssetUsages::default())
179	            .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, self.pos)
180	            .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, self.nrm)
181	            .with_inserted_attribute(Mesh::ATTRIBUTE_COLOR, self.col)
182	            .with_inserted_indices(Indices::U32(self.idx))
183	    }
184	}
