186	/// Five-tier pine: bark trunk + ragged needle tiers with per-variant tone and scale.
187	fn pine_mesh(variant: u32) -> Mesh {
188	    let mut acc = MeshAcc::default();
189	    let v = variant * 17 + 3;
190	    let bark = rgb(0.075 + 0.02 * hash01(v), 0.040, 0.022);
191	    acc.push(&cyl(0.26, 3.4, 8), Transform::from_xyz(0.0, 1.7, 0.0), |p| p * Vec3::new(1.0 - 0.35 * (p.y + 1.7) / 3.4, 1.0, 1.0 - 0.35 * (p.y + 1.7) / 3.4), |p, _| mulc(bark, 0.7 + 0.5 * (p.y + 1.7) / 3.4));
192	    let hue = hash01(v + 1);
193	    let dark = rgb(0.014 + 0.012 * hue, 0.075 + 0.04 * hue, 0.03);
194	    let light = rgb(0.045 + 0.03 * hue, 0.17 + 0.05 * hue, 0.05);
195	    for k in 0..5u32 {
196	        let t = k as f32 / 4.0;
197	        let radius = (2.15 - 1.35 * t) * (0.92 + 0.16 * hash01(v + 10 + k));
198	        let height = 2.6 - 0.8 * t;
199	        let base_y = 1.7 + k as f32 * 1.12;
200	        let tier_tone = 0.8 + 0.4 * hash01(v + 20 + k);
201	        let seed = (v + k) as f32;
202	        let h = height;
203	        acc.push(
204	            &cone(radius, height, 14),
205	            Transform::from_xyz(0.0, base_y + height * 0.5, 0.0).with_rotation(Quat::from_rotation_y(hash01(v + 30 + k) * TAU)),
206	            move |p| {
207	                // ragged skirt: radial wobble strongest at the base ring
208	                let w = (1.0 - (p.y + h * 0.5) / h).clamp(0.0, 1.0);
209	                let a = p.z.atan2(p.x);
210	                let f = 1.0 + 0.22 * w * ((a * 5.0 + seed).sin() * 0.6 + (a * 11.0 + seed * 2.3).sin() * 0.4);
211	                Vec3::new(p.x * f, p.y - 0.12 * w * (a * 7.0 + seed).sin().abs(), p.z * f)
212	            },
213	            move |p, _| mixc(mulc(dark, tier_tone), mulc(light, tier_tone), (p.y + h * 0.5) / h * 0.9 + 0.1),
214	        );
215	    }
216	    acc.plain(&cone(0.16, 1.1, 6), Transform::from_xyz(0.0, 1.7 + 4.0 * 1.12 + 2.0, 0.0), dark);
217	    acc.build()
218	}
