220	/// Faceted noise-deformed boulder; upward faces turn to moss.
221	fn rock_mesh(seed: u32) -> Mesh {
222	    let mut m: Mesh = Sphere::new(1.0).mesh().ico(2).expect("ico");
223	    m.duplicate_vertices();
224	    let perlin = noise::Perlin::new(seed);
225	    let s = seed as f64 * 3.7;
226	    if let Some(VertexAttributeValues::Float32x3(pos)) = m.attribute_mut(Mesh::ATTRIBUTE_POSITION) {
227	        for p in pos.iter_mut() {
228	            let d = Vec3::from(*p).normalize();
229	            let q = [d.x as f64 * 1.4 + s, d.y as f64 * 1.4, d.z as f64 * 1.4];
230	            let q2 = [d.x as f64 * 3.7 + s, d.y as f64 * 3.7, d.z as f64 * 3.7];
231	            let r = 1.0 + 0.30 * perlin.get(q) as f32 + 0.09 * perlin.get(q2) as f32;
232	            let v = d * r * Vec3::new(1.2, 0.85, 1.0);
233	            *p = [v.x, v.y.max(-0.55), v.z];
234	        }
235	    }
236	    m.compute_flat_normals();
237	    let nrm: Vec<[f32; 3]> = m.attribute(Mesh::ATTRIBUTE_NORMAL).and_then(|a| a.as_float3()).unwrap().to_vec();
238	    let pos: Vec<[f32; 3]> = m.attribute(Mesh::ATTRIBUTE_POSITION).and_then(|a| a.as_float3()).unwrap().to_vec();
239	    let mut col = Vec::with_capacity(pos.len());
240	    for (k, n) in nrm.iter().enumerate() {
241	        let p = pos[k];
242	        let n_i = perlin.get([p[0] as f64 * 2.3 + s, p[1] as f64 * 2.3, p[2] as f64 * 2.3]) as f32;
243	        let moss = ((n[1] + 0.25 * n_i - 0.38) / 0.35).clamp(0.0, 1.0);
244	        let tone = 0.75 + 0.35 * (0.5 + 0.5 * n_i);
245	        let stone = rgb(0.14 * tone, 0.14 * tone, 0.15 * tone);
246	        let green = rgb(0.02 + 0.012 * n_i.abs(), 0.065 + 0.03 * n_i.abs(), 0.022);
247	        col.push(mixc(stone, green, moss));
248	    }
249	    m.insert_attribute(Mesh::ATTRIBUTE_COLOR, col);
250	    m
251	}
