253	/// Clump of curved grass/reed blades (one mesh, vertex-coloured base→tip).
254	fn blade_clump(seed: u32, count: u32, height: f32, width: f32, base: [f32; 4], tip: [f32; 4]) -> Mesh {
255	    let (mut pos, mut nrm, mut col, mut idx) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
256	    for b in 0..count {
257	        let r = |k: u32| hash01(seed * 1000 + b * 13 + k);
258	        let (a, dist) = (r(0) * TAU, r(1).sqrt() * 0.22);
259	        let origin = Vec3::new(a.cos() * dist, 0.0, a.sin() * dist);
260	        let lean = r(2) * TAU;
261	        let bend = Vec3::new(lean.cos(), 0.0, lean.sin()) * (0.18 + 0.45 * r(3)) * height;
262	        let h = height * (0.65 + 0.5 * r(4));
263	        let side = Vec3::new(-lean.sin(), 0.0, lean.cos()) * width * 0.5;
264	        let facing = Vec3::new(lean.cos(), 0.0, lean.sin());
265	        let normal = (facing * 0.45 + Vec3::Y * 0.9).normalize().to_array();
266	        let base_i = pos.len() as u32;
267	        let rings = [(0.0_f32, 1.0_f32), (0.5, 0.75), (1.0, 0.0)];
268	        for (k, (t, w)) in rings.iter().enumerate() {
269	            let centre = origin + Vec3::Y * h * *t + bend * t * t;
270	            let c = mixc(mulc(base, 0.7 + 0.5 * r(5)), tip, *t);
271	            if k == 2 {
272	                pos.push(centre.to_array());
273	                nrm.push(normal);
274	                col.push(c);
275	            } else {
276	                pos.push((centre - side * *w).to_array());
277	                pos.push((centre + side * *w).to_array());
278	                nrm.extend([normal, normal]);
279	                col.extend([c, c]);
280	            }
281	        }
282	        idx.extend_from_slice(&[base_i, base_i + 1, base_i + 3, base_i, base_i + 3, base_i + 2, base_i + 2, base_i + 3, base_i + 4]);
283	    }
284	    Mesh::new(PrimitiveTopology::TriangleList, RenderAssetUsages::default())
285	        .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, pos)
286	        .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, nrm)
287	        .with_inserted_attribute(Mesh::ATTRIBUTE_COLOR, col)
288	        .with_inserted_indices(Indices::U32(idx))
289	}
