291	/// A-frame tent with a darker entrance wall.
292	fn tent_mesh() -> Mesh {
293	    let (hx, hz, hy) = (1.45, 1.15, 1.55);
294	    let b = [Vec3::new(-hx, 0.0, -hz), Vec3::new(hx, 0.0, -hz), Vec3::new(hx, 0.0, hz), Vec3::new(-hx, 0.0, hz)];
295	    let r = [Vec3::new(-hx, hy, 0.0), Vec3::new(hx, hy, 0.0)];
296	    let canvas = rgb(0.30, 0.17, 0.065);
297	    let tris: [([Vec3; 3], [f32; 4]); 6] = [
298	        ([b[0], b[1], r[1]], canvas),
299	        ([b[0], r[1], r[0]], canvas),
300	        ([b[2], b[3], r[0]], mulc(canvas, 0.9)),
301	        ([b[2], r[0], r[1]], mulc(canvas, 0.9)),
302	        ([b[3], b[0], r[0]], mulc(canvas, 0.7)),
303	        ([b[1], b[2], r[1]], rgb(0.025, 0.018, 0.012)),
304	    ];
305	    let mut pos = Vec::new();
306	    let mut col = Vec::new();
307	    for (t, c) in tris {
308	        for v in t {
309	            pos.push(v.to_array());
310	            col.push(c);
311	        }
312	    }
313	    let mut m = Mesh::new(PrimitiveTopology::TriangleList, RenderAssetUsages::default())
314	        .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, pos)
315	        .with_inserted_attribute(Mesh::ATTRIBUTE_COLOR, col);
316	    m.compute_flat_normals();
317	    m
318	}
