322	fn build_assets(mut commands: Commands, mut meshes: ResMut<Assets<Mesh>>, mut mats: ResMut<Assets<StandardMaterial>>) {
323	    let mut vc = |rough: f32, double: bool| {
324	        mats.add(StandardMaterial { base_color: Color::WHITE, perceptual_roughness: rough, reflectance: 0.2, double_sided: double, cull_mode: if double { None } else { Some(bevy::render::render_resource::Face::Back) }, ..default() })
325	    };
326	    let (veg, rock, wood, blade, canvas) = (vc(0.9, false), vc(0.85, false), vc(0.8, false), vc(0.7, true), vc(0.9, true));
327	    let mut glow = |emissive: LinearRgba, alpha: AlphaMode| mats.add(StandardMaterial { base_color: Color::srgba(0.0, 0.0, 0.0, 0.9), emissive, alpha_mode: alpha, ..default() });
328	    let flame = [glow(LinearRgba::rgb(9.0, 1.4, 0.15), AlphaMode::Add), glow(LinearRgba::rgb(22.0, 7.0, 0.5), AlphaMode::Add), glow(LinearRgba::rgb(40.0, 26.0, 5.0), AlphaMode::Add)];
329	    let ember = glow(LinearRgba::rgb(7.0, 1.3, 0.15), AlphaMode::Opaque);
330	    let spark = glow(LinearRgba::rgb(30.0, 12.0, 1.5), AlphaMode::Opaque);
331	    let lantern_glass = glow(LinearRgba::rgb(14.0, 7.0, 1.6), AlphaMode::Opaque);
332	
333	    let a = PropAssets {
334	        pines: (0..4).map(|i| meshes.add(pine_mesh(i))).collect(),
335	        rocks: (0..5).map(|i| meshes.add(rock_mesh(11 + i * 7))).collect(),
336	        grass: (0..3).map(|i| meshes.add(blade_clump(i + 1, 16, 0.55, 0.06, rgb(0.03, 0.10, 0.02), rgb(0.16, 0.34, 0.07)))).collect(),
337	        reeds: (0..3).map(|i| meshes.add(blade_clump(i + 40, 10, 1.9, 0.07, rgb(0.07, 0.16, 0.04), rgb(0.34, 0.31, 0.12)))).collect(),
338	        tent: meshes.add(tent_mesh()),
339	        flame_cone: meshes.add(cone(1.0, 1.0, 10)),
340	        spark_mesh: meshes.add(Sphere::new(0.028).mesh().ico(1).expect("ico")),
341	        mats: Palette { veg, rock, wood, blade, canvas, lantern_glass, flame, ember, spark },
342	    };
343	    commands.insert_resource(a);
344	}
