636	fn animate_sparks(time: Res<Time>, mut q: Query<(&mut Spark, &mut Transform)>) {
637	    let dt = time.delta_secs();
638	    for (mut s, mut tf) in &mut q {
639	        s.age += dt;
640	        if s.age >= s.life {
641	            s.age = 0.0;
642	            s.seed = rand::random::<f32>() * TAU;
643	            s.vel = Vec3::new((rand::random::<f32>() - 0.5) * 0.7, 1.2 + 1.8 * rand::random::<f32>(), (rand::random::<f32>() - 0.5) * 0.7);
644	        }
645	        let t = s.age;
646	        let sway = Vec3::new((t * 4.0 + s.seed).sin(), 0.0, (t * 3.3 + s.seed).cos()) * 0.12 * t;
647	        tf.translation = s.origin + s.vel * t - Vec3::Y * 0.15 * t * t + sway;
648	        let k = 1.0 - (t / s.life).powi(2);
649	        tf.scale = Vec3::splat(k.max(0.001));
650	    }
651	}
