            }
        }
        HistSrc::Terrain => {
            if let Some(h) = if undo { th.undo() } else { th.redo() } {
                if h.len() == grid.0.heights.len() {
                    grid.0.heights = h;
                    if let Ok(m) = terrain.single() {
                        let splats = grid.0.build_splatmap(&spec);
                        let _ = meshes.insert(&m.0, build_terrain_mesh(&grid.0, &splats));
                    }
                }
            }
        }
    }
