        if let Some(h) = hit {
            let dt = time.delta_secs().min(0.05);
            if let Some(mode) = kind.mode() {
                let rect = height_dab(&mut grid.0, mode, h.x, h.z, brush.radius, brush.strength, dt, st.target, spec.max_height);
