            let b = s.erased.iter().map(|(e, tf)| ObjState { entity: *e, tf: *tf, alive: true }).collect();
            let a = s.erased.iter().map(|(e, tf)| ObjState { entity: *e, tf: *tf, alive: false }).collect();
            sh.record("Erase Props", b, a);
        }
    }
}

