            let mut next = (*d.spec).clone();
            next.time_of_day = t;
            let mut cur = (*d.spec).clone();
            if ev.changed || ev.finish {
                track_ev(&ev, &mut d.wh, "Time of day", &mut cur, next);
                if ev.changed {
                    *d.spec = cur;
                }
            }
            ui.horizontal_wrapped(|ui| {
                let mut toggle = |ui: &mut egui::Ui, label: &str, on: bool, f: &mut dyn FnMut(&mut WorldSpec)| {
                    if chip(ui, on, label).clicked() {
                        let before = (*d.spec).clone();
                        let mut next = before.clone();
                        f(&mut next);
                        d.wh.record(format!("Toggle {label}"), before, next.clone());
                        *d.spec = next;
                    }
                };
                let s = d.spec.clone();
                toggle(ui, "Reflections", s.reflections, &mut |x| x.reflections = !x.reflections);
                toggle(ui, "Fog", s.fog_enabled, &mut |x| x.fog_enabled = !x.fog_enabled);
